-- ===== 본문 재추출 반영 2/5 (parse800.py 생성) =====
-- 러닝헤더가 끼어든 본문/뒤바뀐 본문을 PDF에서 다시 추출한 값으로 교체. id·코스·진도는 그대로.
-- 이 파일 70행 / 전체 338행

UPDATE public.words SET meaning = '일반적으로 녹색GDP(Green GDP)는 한 나라의 국내총생산(GDP)에서 생산활동 중 발생하는 자연자원의 감소나 환경피해 등의 손실액을 공제한 것으로 이해된다.', detailed_meaning = '일반적으로 녹색GDP(Green GDP)는 한 나라의 국내총생산(GDP)에서 생산활동 중 발생하는 자연자원의 감소나 환경피해 등의 손실액을 공제한 것으로 이해된다. 이는 기존의 GDP가 재화와 서비스를 많이 생산할수록 커지는 반면, 생산활동 과정에서 발생하는 자원고갈, 환경오염 등으로 인해 국민의 후생이 떨어지는 부정적인 효과를 전혀 반영하지 못하는 데서 대안으로 나온 것이다. 경제와 환경을 아우르는 지속가능한 발전의 개념이 처음 등장한 것은 1970년대이나 본격적으로 공론화되기 시작한 것은 1990년대 초반부터로, 2012년 UN은 환경과 경제를 통합적인 관점에서 정량적으로 분석할 수 있는 틀인 환경경제통합계정(SEEA; System of Environmental-Economic Accounting)을 국민계정의 부속계정형태로 채택하고, 2021년 생태계 통계 체계의 표준으로 생태계계정(EA; Ecosystem Accounting)을 채택 후 각국에 이의 이행을 권고한 바 있다. 현재 우리나라는 SEEA의 환경보호지출계정을 도입하여 운영 중이다.', related_words = '{}'::text[] WHERE id = 163;  -- 녹색GDP
UPDATE public.words SET meaning = '주택담보대출 취급 시 담보가치(주택가격) 대비 대출 취급 가능금액의 비율 (Loan-To- Value ratio)을 의미한다.', detailed_meaning = '주택담보대출 취급 시 담보가치(주택가격) 대비 대출 취급 가능금액의 비율 (Loan-To- Value ratio)을 의미한다. 예를 들어 아파트 감정가격이 5억원이고 담보인정비율(LTV)이 70%이면 금융기관으로부터 3억 5천만원의 주택담보대출을 받을 수 있다. 「은행업감독업무시행세칙」에서는 “담보인정비율 = [(담보대출금액+선순위채권+임차보증금 및 최우선변제 소액임차보증금)/담보가치×100” 방식으로 산정하도록 하고 있다. 여기서 담보가치는 ① 국세청의 기준시가 ② 감정평가법인 등의 감정평가액 ③ 한국부동산원의 층별ㆍ호별 격차율 지수로 산정한 가격 ④ KB부동산시세의 ‘일반평균가’ 중 금융기관 자율로 선택하여 적용한다. 당초 LTV 규제는 은행권을 중심으로 내규에 반영하여 자율적으로 시행 ㄷ해 오다가 금융기관의 경영 안정성 유지, 부동산 투기 억제 등을 위한 주택담보대출 규모의 관리 필요성이 제기되면서 2002년 9월 감독규제 수단으로 도입되었다. 이후 가계부채증가 억제 및 부동산경기 조절 등 거시건전성정책 수단으로 활용되고 있으며, 주택 소재지(규제·비규제), 차주 특성(무주택·다주택·생애최초 등) 및 대출목적(주택구입·임대사업등)별로 세분화하여 차등 적용되고 있다. 한편, 금융기관은 주택담보대출 취급시 담보인정비율(LTV)과 함께 차주의 부채상환능력을 나타내는 총부채상환비율(DTI), 총부채원리금상환비율(DSR) 등도 고려하여 대출규모를 결정한다.', related_words = ARRAY['총부채상환비율(DTI)','총부채원리금상환비율(DSR)']::text[] WHERE id = 170;  -- 담보인정비율(LTV)
UPDATE public.words SET meaning = '현물환거래의 결제는 거래당사자 상호 간에 신용위험을 회피하기 위하여 거래계약일과 같은 날짜에 결제가 이루어지는 것을 원칙으로 하고 있다.', detailed_meaning = '현물환거래의 결제는 거래당사자 상호 간에 신용위험을 회피하기 위하여 거래계약일과 같은 날짜에 결제가 이루어지는 것을 원칙으로 하고 있다. 그런데 외환거래의 경우 결제되는 은행의 소재 국가가 서로 다르고 각 국가의 영업일도 다를 수 있기 때문에 결제일의 조정이 필요하게 된다. 이에 따라 현물환거래는 계약을 체결한 시점과 인수·인도가 이 루어지는 시점이 다를 수 있으며, 결제 시점에 따라 다음 세 가지로 분류한다. 당일결제 (value today)는 거래계약일에 외환의 인수·인도와 관련 대금의 결제가 이루어지는 현물환 거래방식이다. 익영업일결제(value tomorrow)는 거래계약 후 1영업일에 결제가 이루어지고, 익익영업일결제(value spot)는 거래계약 후 2영업일에 결제가 이루어지는 거래방식이다. 한편 2영업일 경과 후 결제가 이루어지는 외환거래는 현물환거래가 아니라 선물환거래로 분류한다.', related_words = ARRAY['선물환거래']::text[] WHERE id = 171;  -- 당일결제/익일결제/익익일결제
UPDATE public.words SET meaning = '대량지급(Direct Credit)은 은행지로 업무의 한 유형으로서 급여, 연금, 배당금 등과 같이 일시 또는 정기적으로 발생하는 다수의 고객을 대상으로 동시에 이루어지는 거래를 위하여', detailed_meaning = '대량지급(Direct Credit)은 은행지로 업무의 한 유형으로서 급여, 연금, 배당금 등과 같이 일시 또는 정기적으로 발생하는 다수의 고객을 대상으로 동시에 이루어지는 거래를 위하여 공공기관이나 대기업 등 이용기관의 예금계좌에서 다수의 수취인 예금계좌로 지정된 날짜에 자금을 이체하는 업무이다. 이를 이용하면 하나의 거래은행을 통해서도 전국 모든은행의 수취인 예금계좌로 자금을 이체할 수 있다.', related_words = ARRAY['지로(GIRO)','입금이체']::text[] WHERE id = 173;  -- 대량지급
UPDATE public.words SET meaning = '은행을 포함하여 기업이 보유하는 채권 중에서 거래상대방의 부도 등으로 회수가 어려워 손실이 발생할 수 있는데, 이러한 손실을 충당하기 위해 미리 비용으로 처리해서 사내에 유보해둔 자금을', detailed_meaning = '은행을 포함하여 기업이 보유하는 채권 중에서 거래상대방의 부도 등으로 회수가 어려워 손실이 발생할 수 있는데, 이러한 손실을 충당하기 위해 미리 비용으로 처리해서 사내에 유보해둔 자금을 대손충당금이라고 한다. 「은행업 감독규정」에서는 은행들에게 차주의 채무상환능력 등을 감안하여 자산건전성을 분류하고 이에 따라 대손충당금을 적립하도 록 하고 있다. 은행이 적립한 대손충당금을 비교적 회수가 어려운 고정이하여신 금액으로 나눈 비율을 대손충당금 적립비율이라고 한다.', related_words = ARRAY['고정이하여신비율']::text[] WHERE id = 174;  -- 대손충당금적립비율
UPDATE public.words SET meaning = '2002년 4월 전미경제연구소(NBER; National Bureau of Economic Research) 연례세미나에서 미국 하버드대 스톡(J. Stock) 교수와 프린스턴대 왓슨(M.', detailed_meaning = '2002년 4월 전미경제연구소(NBER; National Bureau of Economic Research) 연례세미나에서 미국 하버드대 스톡(J. Stock) 교수와 프린스턴대 왓슨(M. Watson) 교수가 주요국의 경기순환이 달라졌음을 설명하면서 처음 사용한 용어이다. 1980년대 중반 이후 2007년 금융위기 이전까지 약 20년간 일본을 제외한 주요 선진국에서 산출량, 인플레이 션 등 거시변수의 변동성이 크게 감소하면서 경제가 안정을 누린 기간을 지칭한다. 대안정기(great moderation)는 다양한 원인에서 비롯된 것으로 분석되고 있는데, 2004년 미국 연준의 버냉키(Ben S. Bernanke) 의장은 ‘대안정기(The Great Moderation)’라는 제목의 연설에서 “경제제도, 기술, 사업관행, 경제의 구조적인 특징 변화가 경제의 충격을 흡수하는 능력을 향상시켰고, 주요국 중앙은행들이 인플레이션을 잘 통제하는 등 통화정책의 성과로 경제적 안정이 증대되었으며 경제에 타격을 주는 충격이 적었던 행운도 따랐기 때문”이라고 지적한 바 있다. 그러나 2008년 글로벌 금융위기가 발생하면서 대안정기가 허상 혹은 착시였으며 금융시장에 대한 과신과 과잉 레버리지로 위기를 초래하였다는 주장도 제기되었다.', related_words = ARRAY['골디락스경제']::text[] WHERE id = 175;  -- 대안정기
UPDATE public.words SET meaning = '대외지급준비자산이란 한 나라의 통화 당국이 경제에 큰 영향을 미치지 않고 언제든지 대외 지급에 충당할 수 있도록 보유하고 있는 준비자산(금, SDR, IMF position 및 보유 외화)을', detailed_meaning = '대외지급준비자산이란 한 나라의 통화 당국이 경제에 큰 영향을 미치지 않고 언제든지 대외 지급에 충당할 수 있도록 보유하고 있는 준비자산(금, SDR, IMF position 및 보유 외화)을 말한다. 대외지급준비자산은 외국 채권자가 받아들일 수 있는 수용성, 외국 화폐단위로서 표현될 수 있는 가치의 확실성, 통화 당국이 즉각 활용할 수 있는 유동성을 갖추어야 한다. 한편 중앙은행이나 정부가 국제수지 불균형 보전이나 외환시장 안정을 위해 언제든지 사용할 수 있도록 보유하고 있는 대외지급준비자산을 외환보유액이라고 한다. 외환보유액은 긴급 시 국민경제의 안전판일 뿐만 아니라 환율을 안정시키고 국가 신인도를 높이는 데 기여한다. 외환보유액을 산출하는 방식은 국가별로 상이한데, 대체로 우리나라와 대다수 선진국에서는 공적 외환당국이 보유한 순외화자산만을 계상하고 있다.', related_words = ARRAY['외환보유액','IMF 포지션','특별인출권(SDR)']::text[] WHERE id = 177;  -- 대외지급준비자산
UPDATE public.words SET meaning = '미래 특정일자에 종료될 거래의 상대방이 거래를 취소하거나 파산할 경우, 결제일 전에 결제가 이행되지 못할 가능성을 감안하여 다른 거래로 대체하는 과정에서 발생할 비용리스크를 의미한다.', detailed_meaning = '미래 특정일자에 종료될 거래의 상대방이 거래를 취소하거나 파산할 경우, 결제일 전에 결제가 이행되지 못할 가능성을 감안하여 다른 거래로 대체하는 과정에서 발생할 비용리스크를 의미한다. 거래 당사자는 상대방의 거래 취소 또는 부도 등으로 자신의 포지션을 헤지하지 못하거나 현재 포지션에서 발생하는 미실현 이익을 얻지 못할 수 있으며 이 에 따른 리스크 노출액은 현행 시장가격으로 원거래를 대체하는데 드는 비용과 동일하다. 한 예로 외환거래의 최종결제 이전에 거래상대방이 거래를 취소하거나 파산할 경우 해당거래를 다른 거래로 대체하는 과정에서 불리한 환율 변동으로 인해 비용이 발생할 리스크를 들 수 있다. 다른 예를 들면, A은행이 B은행과 금리파생상품을 계약하고 동 거래를 헤지하기 위해 C은행과 다른 금리파생상품을 계약하였다가, 결제일 전에 C은행이 파산으로 결제불이행이 발생할 경우 A은행은 대체비용리스크에 직면하게 된다. 2008년 9월 리먼브라더스사가 파산하면서 결제불이행 사태가 대량으로 발생했던 것이 대표적인 사례이 다. 이와 같이 대체비용리스크는 거래상대방의 거래 취소 또는 부도 등이 빈번한 외환거래, 파생상품 거래 등에서 주로 발생한다.', related_words = ARRAY['외환결제리스크','증권결제리스크']::text[] WHERE id = 178;  -- 대체비용리스크
UPDATE public.words SET meaning = '대출채권 유동화 방법의 하나로서, 대출을 취급한 금융기관이 대출채권의 전부 또는 일부를 타인(참가자 또는 투자자)에게 매각하는 것을 말한다.', detailed_meaning = '대출채권 유동화 방법의 하나로서, 대출을 취급한 금융기관이 대출채권의 전부 또는 일부를 타인(참가자 또는 투자자)에게 매각하는 것을 말한다. 금융기관이 차주와의 채권 채무관계를 유지한 채 원리금 수취권만을 양도하게 되어 있어 참가자가 대출채권에 대한 위험을 부담하게 된다. 즉 금융기관이 채무자로부터 원리금을 회수하는 경우에 한하여 원리금을 수취할 수 있게 된다. 동 거래는 채권을 처분한 대출 금융기관이 여전히 계약상의 채권자로 남아 있어, 채무자에게 대출채권 분할매각 사실을 통지하지 않아도 되는 장점이 있다.', related_words = '{}'::text[] WHERE id = 180;  -- 대출채권 분할매각
UPDATE public.words SET meaning = '도덕적 해이는 거래당사자의 한쪽이 상대보다 양질의 정보를 더 많이 가지고 있는 상태 (정보의 비대칭성)에서 계약이 이루어진 후에 나타날 수 있는 문제이다.', detailed_meaning = '도덕적 해이는 거래당사자의 한쪽이 상대보다 양질의 정보를 더 많이 가지고 있는 상태 (정보의 비대칭성)에서 계약이 이루어진 후에 나타날 수 있는 문제이다. 예를 들면 주주와 전문경영인, 은행과 차입자 간의 계약을 들 수 있다. 전문경영인은 회사의 경영상황에 대해 주주보다 더 많은 정보를 가지고 주주가 아닌 자신의 이익을 극대화하는 경우가 있을 수 있다. 이를 전문경영인의 도덕적 해이라 한다. 또한 은행으로부터 대출을 받은 차입자가 계약대로 차입금을 적절한 투자에 사용하는지를 은행이 정확히 확인할 수 없기때문에 발생하는 문제는 차입자의 도덕적 해이에 해당한다. 도덕적 해이를 해결하기 위해서는 정보의 비대칭성을 완화하거나, 전문경영인이나 차입자(대리인)의 이해를 주주나 은행(주인)의 이해와 일치시키는 장치를 마련하는 게 중요하다. 여기서 주인과 대리인의 이해가 일치하지 않아 발생하는 문제를 주인-대리인 문제 또는 대리인 문제라고 한 다. 한편 정보의 비대칭성 상태에서 계약이 이루어지기 전에 나타날 수 있는 문제로는 역선택이 있다. ㄷ', related_words = ARRAY['역선택','정보의 비대칭성']::text[] WHERE id = 181;  -- 도덕적 해이
UPDATE public.words SET meaning = '동 법은 미국에서 2008년의 글로벌 금융위기가 발생한 이후 이러한 위기의 재발을 방지하기 위해 오바마 정부가 제안한 내용을 반영하여 2010년 7월에 제정되었으며 1930 년대 대공황기의', detailed_meaning = '동 법은 미국에서 2008년의 글로벌 금융위기가 발생한 이후 이러한 위기의 재발을 방지하기 위해 오바마 정부가 제안한 내용을 반영하여 2010년 7월에 제정되었으며 1930 년대 대공황기의 금융개혁 이후 가장 광범위한 개혁방안을 담고 있다. 동 법의 공식 명칭은 「도드-프랭크 월가 개혁 및 소비자보호법(Dodd-Frank Wall Street Reform and Consumer Protection Act)」이다. 동 법안을 입안한 미상원 은행위원회 위원장 크리스 도드(Chris Dodd)와 미하원 금융서비스위원회 위원장 바니 프랭크(Barney Frank) 의 이름을 따서 명명되었다. 동 법은 금융시스템리스크 예방을 위한 금융안정감시위원회 (Financial Stability Oversight Council) 신설, 금융회사 정리절차 개선, 대마불사(大馬 不死) 관행을 막기 위한 대형 은행의 자본확충 의무화, 금융감독기구별 역할 정비, 금융소비자 보호 강화를 위한 소비자금융보호국(Bureau of Consumer Financial Protection) 신설, 장외파생금융상품 등에 대한 규제·감독 강화 등 매우 광범위한 금융규제방안을 담고 있으며, 특히 은행의 자기계정투자(proprietary trading)를 금지하는 볼커룰(Volcker Rule)을 포함하고 있어 1930년대 글래스-스티걸법의 부활이라는 평가를 받고 있다.', related_words = ARRAY['볼커룰']::text[] WHERE id = 182;  -- 도드-프랭크법
UPDATE public.words SET meaning = '동남아시아의 지역협력기구로서 아세안(ASEAN; Association of South-East Asian Nations)이라고도 부른다.', detailed_meaning = '동남아시아의 지역협력기구로서 아세안(ASEAN; Association of South-East Asian Nations)이라고도 부른다. 동남아시아 지역협력의 촉진, 외국의 간섭 배제 및 역내 국가의 평화와 안정 수호, 경제·사회·문화·기술 등 각 분야에서의 상호원조를 설립목적으로 하고 있다. 회원국은 1967년 8월 창설 당시 필리핀, 말레이시아, 싱가포르, 인도네시아, 태국 등 5개국이었으나 1984년 브루나이, 1995년 베트남, 1997년 라오스와 미얀 마, 1999년 캄보디아가 차례로 가입하면서 총 10개국으로 늘어났다. 주요 기구로는 정상회의, 외교장관회의, 상임위원회와 함께 상설 사무국을 인도네시아 자카르타에 두고 있다. 1997년 창설 30주년을 맞아 공동의 비전으로 ASEAN Vision 2020을 도입하였고 이 에 따라 아세안정치보안공동체, 아세안경제공동체, 아세안사회문화공동체를 축으로 하는 역내 통합을 추구하고 있으며 2015년 12월 아세안경제공동체를 출범시킴으로써 단일시장 구축을 추진하고 있다. 이와 함께 역외 국가들과도 대화 관계를 수립해 경제·안보·문화 등의 영역에서 협력을 도모하고 있는데 이러한 대화 상대국은 한국을 비롯하여 미국, 일본, 중국, 러시아, 캐나다, 호주, 뉴질랜드, 인도, EU 등이다.', related_words = ARRAY['치앙마이 이니셔티브(CMI)','치앙마이 이니셔티브 다자화(CMIM)']::text[] WHERE id = 183;  -- 동남아시아국가연합(ASEAN)
UPDATE public.words SET meaning = '개별 경제지표로는 파악하기 어려운 국민경제의 총체적인 경기수준을 파악하기 위하여경기종합지수를 작성한다.', detailed_meaning = '개별 경제지표로는 파악하기 어려운 국민경제의 총체적인 경기수준을 파악하기 위하여경기종합지수를 작성한다. 경기종합지수는 선행종합지수, 동행종합지수, 후행종합지수등 세 종류가 작성되는데 기준년도 수치가 100이 되도록 하여 산출하고 있다. 동행종합지수는 광공업생산지수, 서비스업생산지수(도소매업 제외), 건설기성액, 소매판매액지수, 내수출하지수, 수입액, 비농림어업취업지수 등 경기순환과 함께 변동하는 7개 개별지표를 가공·종합하여 만들어진다. 다만 현재의 경기상황을 판단하는 데는 동행종합지수에서 추세변동을 제거한 동행종합지수 순환변동치를 주로 사용한다. 경기종합지수는 경기의 종합적인 움직임을 가늠할 수 있다는 장점이 있으나 작성상 한계가 있는 만큼 개별 경제지표의 움직임도 함께 살펴보아야 한다.', related_words = ARRAY['경기종합지수','후행종합지수']::text[] WHERE id = 185;  -- 동행종합지수
UPDATE public.words SET meaning = '등록발행이란 채권을 실물발행(physical issue)하지 않고 한국예탁결제원 등 등록기관이 관리하는 채권등록부에 채권자의 성명, 주소, 채권금액 등 권리내역을 등록(book-entry)', detailed_meaning = '등록발행이란 채권을 실물발행(physical issue)하지 않고 한국예탁결제원 등 등록기관이 관리하는 채권등록부에 채권자의 성명, 주소, 채권금액 등 권리내역을 등록(book-entry) 함으로써 증서의 점유 없이도 채권자의 법적 권리를 보장하는 것을 말한다. 채권자는 등록절차를 마침으로써 채권자로서의 권리가 확보되며, 채권의 매매, 질권 및 담보권의 설정, 신탁재산의 표시 등은 채권등록부 기재를 통하여 해당 채권의 발행자 및 제3자에게대항할 수 있다. 채권 발행자 입장에서는 실물 발행비용이 절감되고, 원리금을 지급할 때실물 확인절차를 생략할 수 있는 등 업무처리가 간편해지는 이점이 있다. 채권자의 입장에서도 실물보관에 따른 위험부담이 없고 보관비용이 절감되는 이점이 있다. 현재 대부분의 채권은 실물발행 없이 등록발행되고 있다. 국고채 등 대부분의 국채와 통화안정증권은 한국은행이, 금융채·회사채 등 여타 채권은 한국예탁결제원이 각각 등록업무를 담당하고 있다. CD의 경우 2006년 6월부터 CD 등록발행제가 시행됨에 따라 은행들이 금융기관을 대상으로 CD를 발행하는 경우 대부분 CD를 실물발행하지 않고 한국예탁결제원을 통해등록발행하고 있다.', related_words = '{}'::text[] WHERE id = 187;  -- 등록발행
UPDATE public.words SET meaning = '미국의 경제학자 래퍼(A. Laffer)가 제시한 조세수입과 세율 간의 관계를 나타낸 곡선을 말한다.', detailed_meaning = '미국의 경제학자 래퍼(A. Laffer)가 제시한 조세수입과 세율 간의 관계를 나타낸 곡선을 말한다. 래퍼는 세율이 0%에서 100%로 증가할 때 조세수입은 상승하다가 정점에 이른후 다시 하강한다면서, 세율(t)을 수평축에 조세수입(T)을 수직축에 놓고 이들의 관계를 그려보면 아래 그림과 같이 “역 U자 모양의 곡선”이 된다고 주장하였다. 래퍼곡선(Laffer curve)에 따르면 세율이 높아지면 초기에는 세수가 늘어나나 일정 수준(t*)이 넘으면 오히려 감소하므로 현재의 세율이 세수가 가장 많은 수준(t*)을 넘지 않았다면 세수증대를 위해서는 세율을 올려야 하며 반대로 현재의 세율이 세수가 가장 많은 수준을 넘었다면 세율 인하가 세수증대에 도움이 된다. 래퍼곡선은 미국 레이건 정권의 감세정책을 뒷받침한 이론적 근거로 널리 이용되었으나 조세수입을 극대화시키는 최적세율이 어느 정도 수준인지는 정확하게 제시하지 못한다는 한계가 있다.', related_words = ARRAY['조세부담률']::text[] WHERE id = 192;  -- 래퍼곡선
UPDATE public.words SET meaning = '레그테크(RT; RegTech, Regulatory Technology)는 금융업 등 산업 전반에 걸쳐 혁신정보기술(IT)과 규제를 결합하여 규제관련 요구사항 및 절차를 효율적으로 처리하는', detailed_meaning = '레그테크(RT; RegTech, Regulatory Technology)는 금융업 등 산업 전반에 걸쳐 혁신정보기술(IT)과 규제를 결합하여 규제관련 요구사항 및 절차를 효율적으로 처리하는 기술또는 회사를 뜻한다. 이는 금융서비스 산업의 새 영역이자 일종의 핀테크(FinTech)이다.레그테크회사들은 수작업의 자동화, 분석·보고절차의 연결, 데이터 품질 개선, 데이터에 대한 전체적인 시각의 창출, 절차관련 앱(application)에 의한 데이터 자동 분석, 핵심 사업에 대한 의사결정 및 규제당국 앞 송부용 보고서 생산에 초점을 맞춘다.', related_words = ARRAY['‌핀테크','고객확인절차(KYC)','블록체인','분산원장기술']::text[] WHERE id = 193;  -- 레그테크
UPDATE public.words SET meaning = '안정성을 추구하는 저축과 달리 투자에서는 종종 레버리지 효과(Leverage Effect)가 발생한다.', detailed_meaning = '안정성을 추구하는 저축과 달리 투자에서는 종종 레버리지 효과(Leverage Effect)가 발생한다. 금융에서는 실제 가격변동률보다 몇 배 많은 투자수익률이 발생하는 현상을 지렛대에 비유하여 레버리지로 표현한다. 투자에서 가격변동률보다 몇 배 많은 투자수익률이 발생하려면, 즉 레버리지 효과가 나타나려면, 투자액의 일부가 부채로 조달되어야 한 다. 레버리지 효과는 총투자액 중에서 부채의 비중이 커지면(자기자본의 비중이 작아지면) 증가하게 된다. 레버리지가 내재한 투자의 예로, 전세를 끼고 주택을 매입한 경우를 상정해보자. 10억원인 아파트를 8억원의 전세를 끼고 자기자본 2억원으로 매입하였다 면, 투자 레버리지(=총투자액/자기자본)는 5배(=10억원/2억원)가 된다. 이후 집값이 10% 상승하여 11억원이 되면 자기자본 2억원에 대한 투자수익률은 실제 가격변동률(10%)의 5배인 50%가 된다. 만일 집값이 30% 하락하여 7억원이 되면 투자수익률은 실제 가격변동률(-30%)의 5배인 -150%가 되어 집값이 전세값에도 못 미치는 소위 ‘깡통 전세’로 전락하게 된다. 이와 같이 레버리지는 손익을 확대시키는 효과가 있으므로 레버리지는 ‘양날의 칼’에 비유되기도 한다. 1997년말 한국에 외환위기가 닥쳤을 때 많은 사업자와 기업이 파산하게 된 원인 중 하나가 부채에 의존한 높은 레버리지였다. 그러므로 투자를 할 때는 감내할 만한 수준 이내로 부채를 적절하게 활용하는 것이 바람직하다.', related_words = ARRAY['디레버리징']::text[] WHERE id = 194;  -- 레버리지 효과
UPDATE public.words SET meaning = '레버리지비율(Leverage Ratio)은 ‘[기본자본(Tier 1) / 총익스포저(난외자산 포함)] × 100’으로 정의된다.', detailed_meaning = '레버리지비율(Leverage Ratio)은 ‘[기본자본(Tier 1) / 총익스포저(난외자산 포함)] × 100’으로 정의된다. 분자의 자본은 바젤Ⅲ 기준 기본자본(Tier 1)을 사용하며 분모의 총익스포저는 자기자본비율을 산정할 경우에 적용되는 위험가중자산과는 달리 명목가액을 기준으로 하여 산출한다. 자기자본비율 규제 하에서 은행은 호황기에 보유자산의 위험가 중치를 낮게 설정함으로써 외형상 높은 자기자본 수준을 유지하면서 레버리지를 확대할수 있었다. 이 경우 위기 발생시 급격한 디레버리징(자산처분, 부채상환)이 발생하여 위기가 증폭되는 악순환이 발생할 수 있는데, 레버리지비율 규제는 이러한 자기자본비율 규제의 문제점을 보완한다고 할 수 있다. 바젤은행감독위원회(BCBS)는 2015년 1월부터 레버리지비율 공시를 의무화하였으며 은행들은 2018년 1월부터 최저 레버리지비율(3%)도 준수해야 한다. 이 밖에도 글로벌 시스템적 중요 은행(G-SIB)에게는 2022년 1월부터 시스템적중요도에 따라 국별로 추가 레버리지비율이 적용되고 있다. 이는 위험가중자산 기반 자기자본비율 규제에서 G-SIB에 대해 부과하고 있는 추가자본 규제와의 일관성을 갖추기 위한 것으로 G-SIB은 자기자본비율 규제상 부과되는 추가자본의 50%만큼 상향 조정된 레버리지비율을 준수해야 한다. 예를 들어 2%의 추가자본이 부과된 G-SIB이 준수해야 할레버리지비율은 최저 레버리지비율 3%에 추가자본의 50%에 해당하는 1%가 가산된 4% 가 된다. G-SIB이 동 레버리지비율을 준수하지 못할 경우, 추가자본의 미준수시와 동일 ㄹ하게 이익배분이 제한된다. 우리나라는 레버리지비율을 「은행업감독규정」에서 단순기본자본비율로 정의하고 있으며 2015년 1분기부터 보조지표로 공시된 후 2018년부터 동 규제(3% 이상)가 시행되었으며 2020년 1월부터는 인터넷전문은행에도 적용되었다.', related_words = ARRAY['기본자본(Tier 1)','익스포저','디레버리징']::text[] WHERE id = 195;  -- 레버리지비율/단순기본자본비율
UPDATE public.words SET meaning = '1905년 미국의 통계학자인 로렌츠(M. Lorenz)가 소득의 불평등 정도를 측정하기 위해제안한 것으로, 인구의 누적비율을 가로축에 소득의 누적점유율을 세로축에 놓고 이들의 관계를 그림으로', detailed_meaning = '1905년 미국의 통계학자인 로렌츠(M. Lorenz)가 소득의 불평등 정도를 측정하기 위해제안한 것으로, 인구의 누적비율을 가로축에 소득의 누적점유율을 세로축에 놓고 이들의 관계를 그림으로 표시한 곡선을 말한다. 모든 사람의 소득이 일정하다면 인구가 누적되어도 소득 누적액이 일정할 것이므로 로렌츠 곡선(Lorenz Curve)은 아래 그림의 OO′선과 같은 대각선이 된다. 반면 소득이 불평등하다면 처음에는 소득이 적은 사람들의 누적액이 더해져 그래프의 기울기가 완만하다가 뒤로 갈수록 소득이 많은 사람들의 누적액이 더해지면서 가파른 모양의 아래로 늘어진 곡선이 된다. 극단적으로 한 사람이 모든 소득을 다 가지고 있는 경우에는 OTO′선과 같은 모양이 된다. 따라서 로렌츠 곡선이 OO′선에 가 까워질수록 분배상태가 평등하고, OTO′선에 가까워질수록 불평등 정도가 높다고 판단할수 있다. 로렌츠 곡선은 한 나라의 소득분배 상태를 그림으로 볼 수 있다는 장점이 있으나 그 정도를 정량적으로 표시할 수 없다는 단점이 있다. 소득분배 상태를 정량적으로 파악하기 위해서는 지니계수를 이용하여야 한다. 지니계수는 아래 그림의 대각선과 로렌츠곡선 사이의 면적을 대각선 아래 삼각형 면적 전체로 나눈 것으로, 소득분배가 완전히 평등 하다면 대각선과 로렌츠곡선 사이의 면적이 0이 되어 지니계수는 0이 된다. 반대로 소득분배가 완전히 불평등하다면 대각선과 로렌츠곡선 사이의 면적이 대각선 아래 전체 면적과 같게 되므로 지니계수는 1이 된다. 100 0′ 소득 누적점유율소득의 완전 균등분배를 나타내는 대각선( 로렌츠 곡선% ) T 0 인구의 누적비율(%) 100', related_words = ARRAY['지니계수']::text[] WHERE id = 196;  -- 로렌츠곡선
UPDATE public.words SET meaning = '리디노미네이션(Redenomination) 또는 ‘화폐단위 변경’이란 구매력이 다른 새로운 화폐단위를 만들어 현재의 화폐단위로 표시된 가격, 증권의 액면가, 예금·채권·채무 등 일체의 금액을', detailed_meaning = '리디노미네이션(Redenomination) 또는 ‘화폐단위 변경’이란 구매력이 다른 새로운 화폐단위를 만들어 현재의 화폐단위로 표시된 가격, 증권의 액면가, 예금·채권·채무 등 일체의 금액을 법정비율(교환비율)에 따라 일률적으로 조정하여 새로운 화폐단위로 표기 및호칭하는 것을 의미한다. 보통 리디노미네이션은 지속적인 인플레이션으로 인해 재화와 서비스의 교환가치를 화폐로 나타내는 숫자가 많아서 초래되는 계산 및 회계기장 등의 불편을 해소할 목적으로 시행된다. 또한 자국 통화의 대외적 위상을 높일 목적으로 시행되기도 한다. 우리나라에서는 1953년의 제1차 통화조치에 따라 100원(圓)이 1환(圜)으로, 1962년의 제2차 통화조치에 따라 10환(圜)이 1원으로 변경된 사례가 있다.', related_words = '{}'::text[] WHERE id = 198;  -- 리디노미네이션
UPDATE public.words SET meaning = '마샬의 k(Marshallian k)는 경제 전체의 명목소득 대비 통화량 보유 비율을 의미한다.', detailed_meaning = '마샬의 k(Marshallian k)는 경제 전체의 명목소득 대비 통화량 보유 비율을 의미한다. 어떤 경제에서 일정 기간 동안 명목국민소득이 PY이고 화폐의 유통속도가 V일 경우 실물거래를 위해 필요한 화폐의 양, 즉 화폐의 수요는 다음과 같이 구할 수 있다. 거래수량설방정식 MV=PY에 따르면 M=1/V×PY=kPY의 관계가 도출된다. 따라서 마샬의 k는 화폐유통속도의 역수와 동일한 값을 갖는 상수에 해당한다. 이 이론은 화폐의 유통속도가 일정함을 전제로 하고 있다. 그러나 화폐의 유통속도는 결제 수단의 발전 등 여러 가지 제도 적 요인에 영향을 받을 뿐만 아니라 단기적으로도 매우 변동이 심하게 나타난다. 경기가 호황일 때에는 유통속도가 빨라지고 불황일 때는 늦어지는 경기순응적 움직임을 보인다. 한편 마샬의 k는 MS=Md=kPY에 의거 한 나라의 경제규모 대비 통화공급의 적정 수준을 판단하는 지표로 사용되기도 한다. 그러나 현실적으로 통화량이 다양하게 정의(현금통화, M1, M2, Lf 등)될 뿐만 아니라 금융제도의 혁신 등으로 유통속도도 많이 변하기 때문에 마샬의 k의 적정 수준을 사전적으로 정하는 것은 매우 어려운 일이다.', related_words = '{}'::text[] WHERE id = 200;  -- 마샬의 k
UPDATE public.words SET meaning = '마스트리히트조약(Maastricht Treaty)은 유럽공동체(EC)의 12개 회원국(벨기에, 덴마크, 독일, 그리스, 스페인, 프랑스, 아일랜드, 룩셈부르크, 이탈리아, 네덜란드, 포르투갈,', detailed_meaning = '마스트리히트조약(Maastricht Treaty)은 유럽공동체(EC)의 12개 회원국(벨기에, 덴마크, 독일, 그리스, 스페인, 프랑스, 아일랜드, 룩셈부르크, 이탈리아, 네덜란드, 포르투갈, 영국)이 1992년 2월 7일 네덜란드 마스트리히트에서 서명하고, 1993년 11월 1일부터 발효된 조약으로 정식 명칭은 유럽연합조약(Treaty on European Union)이다. 이 조약은 EC 가 시장 통합을 넘어 정치·경제적 통합체로 결합하는 토대가 되었으며, 유럽중앙은행 창설 및 단일통화 사용의 경제통화동맹(EMU) 달성, 공동방위정책 형성, 유럽연합 시민권제도 도입, 사법 및 치안에 관한 협력 등을 핵심내용으로 하고 있다. 이에 따라 유럽공동체 (EC)는 명칭을 유럽연합(EU)으로 변경하여 새롭게 출범하면서 단일통화를 단계적으로 도 입하기로 하였다. 아울러 유럽경찰 창설에 합의하고 회원국 간의 격차를 해소하기 위한 결속기금 조성을 추진하는 한편 유럽의회의 역할도 조사권, 청원권, 협력절차 도입을 통해 강화하였다.', related_words = ARRAY['유럽연합(EU)','유럽중앙은행(ECB)']::text[] WHERE id = 201;  -- 마스트리히트조약
UPDATE public.words SET meaning = '마찰적 실업 또는 탐색적 실업이란 새로운 일자리를 탐색하거나 이직을 하는 과정에서 일시적으로 발생하는 실업을 의미한다.', detailed_meaning = '마찰적 실업 또는 탐색적 실업이란 새로운 일자리를 탐색하거나 이직을 하는 과정에서 일시적으로 발생하는 실업을 의미한다. 새로운 일자리를 탐색한다는 것은 구직자와 구인자사이에 서로의 요구조건이 일치하지 않는 일종의 마찰이 생겼기 때문으로 볼 수 있다. 마찰적 실업은 경기침체로 인해 발생한 비자발적 실업이 아닌 자발적 실업이며 이는 경기변동 과정에서 발생하는 경기적 실업이나 특정 산업의 침체 등으로 발생하는 구조적 실업과는 구분된다. 노동시장에서 사람들은 탐색으로 인한 이익이 탐색비용을 초과하는 경우 탐색행위를 지속하게 된다. 예를 들어 구인자와 구직자 간에 고려하고 있는 의중임금의 차이가 크거나 구직자가 높은 임금이 기대된다면 실업기간이 길어지더라도 구직행위를 지속하게 된다. 또한 구직자들의 노동의 질이 같지 않고, 구인자들이 제공하는 일자리역시 동질적이지 않기 때문에 구인자들은 좀 더 나은 인재를 찾기 위해, 구직자들은 좀 더나은 일자리를 찾기 위해 탐색행위를 하게 된다. 구직자와 구인자 사이에 정보의 비대칭문제가 사라지지 않고 지속됨에 따라 노동의 수요와 공급의 불일치가 발생하게 되고, 이 러한 탐색 및 마찰로 인해 실업이 발생하게 된다. 따라서 이런 형태의 실업은 언제나 발생할 수 있고, 경기가 좋은 경우에도 발생할 수 있다. 마찰적 실업을 줄이기 위해서는 일자리에 관한 정보를 알려주는 서비스를 대폭 개선하여 노동수요자(구인자)와 노동공급자(구직자) 사이에 원활한 정보교환이 이뤄지도록 하는 것이 중요하다.', related_words = ARRAY['실망실업자','자발적 실업']::text[] WHERE id = 202;  -- 마찰적 실업
UPDATE public.words SET meaning = '머니마켓펀드(MMF; Money Market Fund)는 고객의 일시적인 여유자금을 금리위험과 신용위험이 적은 국공채, 어음 등에 운용하고 동 운용에서 발생하는 수익을 배당하는 펀드의 일종으로서', detailed_meaning = '머니마켓펀드(MMF; Money Market Fund)는 고객의 일시적인 여유자금을 금리위험과 신용위험이 적은 국공채, 어음 등에 운용하고 동 운용에서 발생하는 수익을 배당하는 펀드의 일종으로서 대표적인 단기금융상품이다. MMF로 들어온 자금은 주로 부도 위험이 거의 없는 국채, 통화안정증권 등의 채권, 우량 CP, CD 및 예금 등으로 운용하며 운용자산의 가중평균 잔존만기가 60일(시가평가의 경우는 120일) 이내로 제한된다. 편입자산의 신용등급은 취득시점을 기준으로 상위 2개 등급 이내(채권 AA이상, CP A2 이상)여야 하며 주식과 관련이 있는 채권(전환사채 등)이나 사모발행채권 등은 운용대상 자산에서 제외된다. 2022년 4월부터 법인형 MMF에 대해 시가평가제도가 도입되었으나 안정적 자산의 비중이 30%를 초과하는 MMF의 경우 기존과 같이 장부가 평가가 허용된다. 이에 따라현재 대부분의 MMF는 안정성을 추구하는 투자자의 선호를 반영하여 장부가 평가를 적용받기 위한 운용행태를 나타내고 있다. MMF는 유동성 측면에서 익일 설정 및 익일 환매가 이루어짐에 따라 다른 펀드에 비해 유동성이 높은 편이며 자산의 운용은 자산운용사가, 판매는 은행 및 증권사가 하고 있다.', related_words = ARRAY['단기금융시장','채권시가평가','펀드']::text[] WHERE id = 208;  -- 머니마켓펀드(MMF)
UPDATE public.words SET meaning = '명목GDP목표제란 명목GDP가 사전에 정한 목표수준을 따라가는 것을 목표로 하는 통화정책 운영체제이다.', detailed_meaning = '명목GDP목표제란 명목GDP가 사전에 정한 목표수준을 따라가는 것을 목표로 하는 통화정책 운영체제이다. 이는 글로벌 금융위기 이후 저인플레이션, 저성장, 저금리 현상이 지속됨에 따라 물가안정목표제의 대안으로 일부 학계를 중심으로 제시된 방안이다. 명목 GDP목표제에서는 물가와 실물경제에 동일한 가중치를 부여하기 때문에 경기부진에 보다 적극적으로 대응하는 것이 가능하다. 또한 유가급등과 같은 공급충격으로 물가상승과 생산감소가 동시에 발생하는 경우 어느 정도의 물가상승을 허용하여 생산감소폭을 축소시키는 유연한 정책대응이 가능하다는 장점도 있다. 그러나 명목GDP목표제의 경우 물가 안정에 대한 중앙은행의 신뢰성을 확보하기 어렵고 현실 적합성이 크게 떨어진다는 단점이 있다. 물가와 경기를 동시에 고려하기 때문에 명목기준지표로서의 명료성이 떨어지고 기대 인플레이션을 안정적으로 관리하기가 어렵다. 또한 목표대상지표의 포괄범위도 넓어중앙은행의 통제가능성도 낮다. 이러한 한계로 현재 명목GDP목표제를 실제로 채택한 사례는 아직 없는 상황이다.', related_words = ARRAY['물가안정목표제','제로금리정책','양적완화정책']::text[] WHERE id = 209;  -- 명목GDP목표제
UPDATE public.words SET meaning = '명목소득(Nominal Income)은 대상 경제주체의 소득이 발생할 당시의 가격으로 측정된 소득을 말하며, 실질소득(Real Income)은 통화가치의 변동을 감안하여 명목소득을 기준시점에 맞춰', detailed_meaning = '명목소득(Nominal Income)은 대상 경제주체의 소득이 발생할 당시의 가격으로 측정된 소득을 말하며, 실질소득(Real Income)은 통화가치의 변동을 감안하여 명목소득을 기준시점에 맞춰 조정한 것을 말한다. 예를 들어 2015년에 A씨의 연간 소득을 당시 통화가 치로 측정한 금액이 3,000만원 이라면 명목소득은 3,000만원에 해당한다. 2017년 측정된 A씨의 명목소득이 3,500만원이라면, 2년 동안 A씨의 명목소득은 500만원 증가한 셈이다. 이 경우 A씨의 경제형편이 나아졌는지를 판단하기 위해서는 보다 정확한 정보를 반영하고 있는 실질소득의 변화 여부를 확인해 보아야 한다. 만약 2015~2017년중 인플레이션율(물가상승률)이 15%라면 같은 기간중 통화가치는 15% 하락한 것으로 볼 수 있다. 이 경우 A씨의 2017년 명목소득 3,500만원은 실질소득 기준으로 3,043만원(3500/ (1+0.15))이 된다. 따라서 2015~2017년중 통화가치 변동을 감안할 경우 A씨의 실질소득은 43만원 증가한 것이 된다. 통화의 가치는 인플레이션 등으로 인해 시간이 지날수록 하락하므로 수시로 발표되는 다양한 경제지표를 정확하게 이해하기 위해서는 명목 (nominal)과 실질(real)의 개념으로 구분해서 살펴보아야 한다. 국내총생산에 대한 명목 GDP·실질GDP, 임금에 대한 명목임금·실질임금, 이자율에 대한 명목이자율·실질이자율등은 명목지표와 실질지표를 구분하는 한 예라 하겠다.', related_words = ARRAY['실질임금']::text[] WHERE id = 212;  -- 명목소득/실질소득
UPDATE public.words SET meaning = '모바일뱅킹 서비스는 고객이 휴대전화 등 모바일기기를 이용하여 무선인터넷을 통하여금융기관에 접속하여 이용할 수 있는 금융서비스이다.', detailed_meaning = '모바일뱅킹 서비스는 고객이 휴대전화 등 모바일기기를 이용하여 무선인터넷을 통하여금융기관에 접속하여 이용할 수 있는 금융서비스이다. 이 서비스는 은행이 이동통신회사의 무선인터넷망을 통해 고객의 자금이체 및 계좌조회 등 금융거래과정 전반을 관리하는 것을 기본구조로 하고 있다. 1999년 농협은행 등이 제공하기 시작한 국내 모바일뱅킹 서 비스는 2009년 스마트폰 기반 모바일뱅킹 서비스가 개시된 이후에는 주로 스마트폰을 통해 제공되고 있다. 모바일뱅킹을 통해 제공되고 있는 서비스에는 예금조회, 거래명세조회, 자금이체 등이 있으며, 일부 은행에서는 현금서비스, 대출, 환율조회, 수표조회, 사고 신고 등의 서비스까지 제공하고 있다. 모바일뱅킹 서비스는 대부분의 국내은행 및 우체 ㅁ국, 신용협동조합 및 새마을금고중앙회 등에서 제공되고 있다.', related_words = ARRAY['인터넷뱅킹','텔레뱅킹(폰뱅킹)']::text[] WHERE id = 214;  -- 모바일뱅킹
UPDATE public.words SET meaning = '무위험지표금리(KOFR)는 Korea Overnight Financing Repo Rate의 약자로서, 국채· 통안증권을 담보로 하는 익일물 RP금리를 사용하여 산출한 우리나라의 무위험지표금리', detailed_meaning = '무위험지표금리(KOFR)는 Korea Overnight Financing Repo Rate의 약자로서, 국채· 통안증권을 담보로 하는 익일물 RP금리를 사용하여 산출한 우리나라의 무위험지표금리 (RFR; Risk-Free Reference Rate)이다. 이는 투자자가 신용 리스크 없이 얻을 수 있는 이론상의 최소 수익률을 나타내는 금리로서 LIBOR 금리 조작사건 등 기존 금융거래지표의 신뢰도 하락을 계기로 개발된 대체지표금리이다. KOFR는 국채·통안증권을 담보로 하는 초단기 거래이기 때문에 무위험 금리에 가깝고, 실거래에 기반하여 산출되기 때문에 조작 가능성이 없는 것이 특징이다. 우리나라는 2021년 2월 RFR로 RP거래금리를 최종선정했으며, 증권결제 및 장외 RP거래 환매서비스를 제공하는 기관인 한국예탁결제원이 중요지표 산출기관으로 최종 선정되어 KOFR의 산출·공시 업무를 수행하고 있다. 한국무위험지표금리(KOFR)는 2021년 11월 26일부터 「금융거래지표의 관리에 관한 법률」에 따른 중요지표로서 정식 공시를 시작하였으며, KOFR Index는 2018년 1월 2일을 기준시점으로 1,000을 기준지수로 하여 산출된다. KOFR는 신뢰할 수 있는 지표금리 제공을 통해 금융시장의 안정성을 높이며, 국제적인 금리 기준과의 정합성을 높여 국내 금융시장의 국제화를 촉진한다. 또한, 시장에서 실제로 거래된 금리를 기반으로 산출함으로써 금리 산정의 투명성을 높이는 KOFR는 국내 금융시장에서 중요한 역할을 수행하며, 앞으로 더욱 다양한 분야에서 활용될 것으로 기대된다.', related_words = ARRAY['지표금리','환매조건부채권(RP)']::text[] WHERE id = 217;  -- 무위험지표금리(KOFR)
UPDATE public.words SET meaning = '물가안정목표제(Inflation Targeting)란 중앙은행이 명시적인 중간목표(intermediate target) 없이 일정기간 동안 또는 중장기적으로 달성해야 할 물가상승률 목표치를 미리', detailed_meaning = '물가안정목표제(Inflation Targeting)란 중앙은행이 명시적인 중간목표(intermediate target) 없이 일정기간 동안 또는 중장기적으로 달성해야 할 물가상승률 목표치를 미리 제시하고 이에 맞추어 통화정책을 운영하는 방식이다. 즉, 중앙은행은 통화량, 금리, 환율등 다양한 정보변수를 활용하여 장래의 인플레이션을 예측하고 실제 물가상승률이 목표치에 수렴할 수 있도록 통화정책을 운영하며, 이후 그 성과를 평가하고 시장의 기대와 반응을 반영하면서 정책방향을 수정해 나간다. 물가안정목표제는 다음과 같은 핵심 요소를 포함한다. 첫째로 물가안정목표의 구체적인 수치가 제시되어야 하고, 둘째로 통화정책의 목표 중에서 물가안정이 가장 중요한 목표가 되어야 하며, 셋째로 제시된 목표의 달성에 대한 책임성이 확보되어야 한다는 점이다. 물가안정목표제는 1990년 뉴질랜드에서 처음 도입되었으며, 이후 캐나다, 영국, 스웨덴, 호주 등 선진국과 다수의 신흥시장국으로 확산되었다. 우리나라는 1998년부터 물가안정목표제를 도입하여 시행하고 있다.', related_words = ARRAY['통화정책 운영체제(monetary policy regime)']::text[] WHERE id = 218;  -- 물가안정목표제
UPDATE public.words SET meaning = '투자자들이 자금을 모아 투자 회사를 설립해 주식이나 채권, 파생상품 등에 투자한 후그 운용수익을 투자자, 즉 주주들에게 배당금의 형태로 나누어주는 투자신탁의 하나이 다.', detailed_meaning = '투자자들이 자금을 모아 투자 회사를 설립해 주식이나 채권, 파생상품 등에 투자한 후그 운용수익을 투자자, 즉 주주들에게 배당금의 형태로 나누어주는 투자신탁의 하나이 다. 뮤추얼펀드는 투자자가 유가증권을 직접 매매하는 것이 아니라 전문 펀드매니저를 통해 운용하는 간접투자 방식이다. 제도적으로 회사형과 계약형으로 나눌 수 있고, 주요 투자대상에 따라 단기금융시장, 채권형(또는 고정수입), 주식형(또는 순자산), 혼합형(하이브리드) 등으로 분류된다. 미국의 경우 뮤추얼펀드 이전의 간접투자 제도로는 1868 년 투자조합 형태로 설립된 Foreign Colonial Government Trust가 최초이고 1924년 신탁형태로 보스톤에 설립된 Massachusetts Investors Trust가 있었다. 1940년 투자회사법(Investment Company Act 1940)의 제정으로 법적 기반이 정비되었다. 한편 단기금융시장에 투자하는 MMMF(Money Market Mutual Funds)는 지난 1970년대 금리가 규제되고 있던 시대에 혁신적인 금융상품의 하나로 발전하면서 미국 금융시장에서 금리규제 철폐와 금융자유화를 가속화하는 데 중요한 역할을 한 대표적인 금융혁신 상품으로평가된다. 우리나라는 1998년 9월 증권투자회사법이 제정되어 국제적 형태의 뮤추얼펀드가 도입되었고, 자본시장법에 따라 집합투자기구와 집합투자증권이란 명칭으로 규정되어 있다.', related_words = ARRAY['펀드']::text[] WHERE id = 220;  -- 뮤추얼펀드
UPDATE public.words SET meaning = '미달러화지수(US dollar Index)는 미국 달러화의 가치를 주요 6개국 통화(유로, 엔, 파운드, 캐나다 달러, 스웨덴 크로나, 스위스 프랑) 대비 미달러화 환율을 가중평균하여 측정하는', detailed_meaning = '미달러화지수(US dollar Index)는 미국 달러화의 가치를 주요 6개국 통화(유로, 엔, 파운드, 캐나다 달러, 스웨덴 크로나, 스위스 프랑) 대비 미달러화 환율을 가중평균하여 측정하는 지수다. 1973년 브레튼우즈체제 붕괴 이후 주요국이 변동환율제도로 이행하면서 도입되었으며 기준점은 1973년 3월(100)이다. 지수가 오르면 미달러화 가치가 상승했다 는 뜻이고, 내리면 미달러화 가치가 하락했다는 의미이다. ICE(International Exchange) 와 미국 연방준비제도이사회(FRB; Federal Reserve Board of Governance, 이하 미연준)가 발표하는 지수가 널리 활용되고 있으며, 두 기관의 지수에는 통화별 가중치를 계산하는 방법에서 약간의 차이가 있다. ICE 미달러화지수의 통화별 가중치는 지수를 만들 당시 미국과 해당 국가와의 교역규모 등 경제적 중요성을 반영하여 결정되었다. 이 가중치는 고정적으로 유지되며, 1999년 유로화 출범으로 유럽국가 통화들의 비중을 유로화 단일 통화의 비중으로 합산하는 정도의 수정이 있었다. 2024년 말 현재 통화별 가중치는 유로가 57.6%로 절반 이상을 차지하며 엔 13.6%, 파운드 11.9%, 캐나다 달러 9.1%, 스웨덴 크로나 4.2%, 스위스 프랑 3.6% 순이다. 한편, 미연준의 지수는 미국과의 교역규모를 지속적으로 업데이트하여 산출하며 Trade-Weighted 미달러화지수로도 불린다.', related_words = ARRAY['브레튼우즈체제']::text[] WHERE id = 221;  -- 미달러화지수
UPDATE public.words SET meaning = '미발행화폐란 한국은행이 보유하고 있는 은행권과 주화 중 사용하기에 적합하지 아니하여 폐기(잘게 썰거나, 분쇄 또는 녹이는 등의 방법으로 소각)하기로 결정한 화폐를 제외한 모든 은행권과 주화를', detailed_meaning = '미발행화폐란 한국은행이 보유하고 있는 은행권과 주화 중 사용하기에 적합하지 아니하여 폐기(잘게 썰거나, 분쇄 또는 녹이는 등의 방법으로 소각)하기로 결정한 화폐를 제외한 모든 은행권과 주화를 말한다. 한국은행은 미발행화폐를 필요한 곳에 적기에 공급하기 위하여 한국은행 본부와 각 지역본부에 분산하여 보관하고 있으며 동 화폐의 대부분은 한국조폐공사로부터 제조하여 납품받은 새화폐와 금융기관들이 지급준비금 불입 등을 위해입금한 화폐가 대부분이다. 그리고 한국은행은 미발행화폐를 한국은행 본부 또는 지역본부가 아닌 특정 금융기관에 보관케하는 미발행화폐 임치제도를 운용할 수 있다. 이는 한 국은행 본부 및 지역본부로부터 원격지에 위치하여 교통여건이 열악한 지역의 화폐수급애로를 해소하기 위하여 동 지역소재 금융기관 1개 점포를 지정하여 한국은행의 미발행화폐를 보관케하고 한국은행의 입회, 지시, 감독하에 화폐의 입·출업무를 수행하게 하는 제도이다. 이 제도는 1996년 가장 많은 23개 점포를 지정·운영하였으나 현재는 교통여건개선 등으로 한 곳도 운용하지 않고 있다.', related_words = '{}'::text[] WHERE id = 223;  -- 미발행화폐
UPDATE public.words SET meaning = '1974년 독일 헤르슈타트 은행(Bankhaus Herstatt)의 도산이 국제외환시장 및 은행시스템에 심각한 영향을 미치면서 글로벌 은행감독기준 마련을 위한 공조의 필요성이 대두되었다.', detailed_meaning = '1974년 독일 헤르슈타트 은행(Bankhaus Herstatt)의 도산이 국제외환시장 및 은행시스템에 심각한 영향을 미치면서 글로벌 은행감독기준 마련을 위한 공조의 필요성이 대두되었다. 그 결과 1974년말 G10 국가 중앙은행 총재회의의 결의로 바젤은행감독위원회 (BCBS; Basel Committee on Banking Supervision)가 설립되었다. BCBS는 은행 건전성을 규율하기 위한 국제기준 등을 제정하고 은행감독 관련 사안들에 대한 국제협력의 장을 제공해 왔다. 글로벌 금융위기 이후 BCBS가 은행 규제체계 개혁을 추진하는 과정에서 G10 이외 국가에 문호를 개방하면서 은행 규제·감독 관련 국제기준 제정기구로서의 중요 성은 더욱 커지게 되었다. 2024년 5월 14일 현재 G20 국가를 포함한 28개국(EU 포함)의 45개 중앙은행 및 은행감독기관이 회원으로, 非회원국 중앙은행, 감독기관 협의체, 국제기구 등 9개 기관이 초청기관 자격으로 참여하고 있다. 우리나라는 2009년 3월 한국은행과 금융감독원이 BCBS에 가입하였다.', related_words = '{}'::text[] WHERE id = 225;  -- 바젤은행감독위원회/ 바젤위원회(BCBS)
UPDATE public.words SET meaning = '반대매매(Reverse Trading)란 만기까지 대출금을 갚지 못하거나 담보가치가 일정 비율이하로 떨어지면 증권사가 주식을 강제로 처분하는 것을 의미한다.', detailed_meaning = '반대매매(Reverse Trading)란 만기까지 대출금을 갚지 못하거나 담보가치가 일정 비율이하로 떨어지면 증권사가 주식을 강제로 처분하는 것을 의미한다. 신용매매(보유 주식을 담보로 하여 증권사 자금으로 거래), 스탁론 서비스(외상으로 주식 매수), 미수 거래(담보없는 위탁매매) 계좌를 이용해 주식을 매입했을 경우 주가하락에 따른 담보비율 하락으로 반대매매가 쏟아질 수 있다. 통상 미수거래의 경우에는 3일, 신용거래의 경우에는 1달~3 달이 상환기한이며 이 기간 안에 반대매매를 통해 상환하지 않는 경우나 담보가치가 일정 비율 이하로 하락할 때는 증권사에서 임의적으로 반대매매를 실시한다. 반대매매는 전날 종가 대비 20~30% 낮은 금액으로 주문이 산정되기 때문에 주가에 악영향을 미친다. 특히 개인투자자 지분율이 높은 코스닥시장 종목에 미치는 영향이 크다. 반대매매의 종류에는 크게 세 가지가 있다. 먼저 개장과 동시에 이뤄지는 반대매매다. 증권사로부터 돈을 빌린 신용융자, 예탁증권담보대출의 담보비율이 일정 수준 이하로 내려갔을 때 발생한 다. 둘째, 증권사로부터 돈을 빌려 주식을 사고 2거래일 뒤에 상환하는 미수거래도 만기안에 갚지 못할 경우 장 시작 전 동시호가 때 반대매매로 처분된다. 신용융자와 예탁증권담보대출의 담보비율은 증권사와 종목마다 다르지만 통상 140% 안팎 수준이다. 예를 들어 자기자금 1억원과 대출금 1억원을 합친 2억원으로 주식을 매입할 경우 대출금 1억원의 140%인 1억4000만원 상당의 주식을 갖고 있어야 한다. 주식의 가치가 그 밑으로 떨어지면 증권사가 추가 증거금을 요구한다. 담보부족이 발생하면 투자자들은 다음날까지부족 금액을 채워 넣어야 한다. 그렇지 못할 경우 2거래일 뒤 증권사에서 강제로 반대매매에 나선다. 차액결제거래(CFD)는 주식 등 기초자산을 보유하지 않고 가격 변동에 따른차익만 결제하는 파생상품을 말하는데 일반 현물 주식 매매와 달리 거래 과정에 외국계증권사가 포함된다. 국내 투자자가 주문하더라도 실제 사고파는 주체가 외국계 증권사이 기 때문에 투자 주체별 거래 실적에 외국인 수급으로 잡힌다. 오전 10시를 전후로 외국인매도가 쏟아진다면 CFD 반대매매 물량으로 추정할 수 있다. 마지막으로 오후 2시에는 저축은행과 캐피털사로부터 자금을 빌린 주식매입자금대출(스탁론)의 반대매매가 나온다.스탁론의 담보비율은 통상 120% 안팎으로 증권사가 제공하는 신용융자나 예탁증권담보', related_words = ARRAY['신용거래','담보비율']::text[] WHERE id = 226;  -- 반대매매
UPDATE public.words SET meaning = '발행시장(Primary Market)이란 주식이나 채권 등의 유가증권을 신규로 발행하는 시장을 말한다.', detailed_meaning = '발행시장(Primary Market)이란 주식이나 채권 등의 유가증권을 신규로 발행하는 시장을 말한다. 발행시장 내에서는 자금을 필요로 하는 기업, 금융기관, 정부, 지방공공단체 등 (발행주체)이 유가증권을 최초로 발행하여 자금공급자인 가계나 기관투자가 등(투자주체) 에게 제공하고 소정의 자금을 조달하는 일련의 과정이 발생한다. 발행시장 참여자에는 이 러한 발행주체와 투자주체 외에 인수기관이 있다. 인수기관은 발행주체를 대신하여 증권발행에 수반되는 사무 절차를 처리하고 유가증권 인수업무 등을 수행한다. 이중 채권 발행은 정부, 지방공공단체, 기업, 금융기관 등이 필요 자금을 조달하기 위해 일정한 이자를 지급할 것을 약속하며 발행하는 유가증권으로, 국채, 지방채, 회사채 등 다양한 종류가 있다. 발행시장에서 채권이 신규로 발행되어 투자자에게 판매되며, 이를 통해 발행주체는 장기 자금을 확보한다. 한편 이중 주식 발행은 기업공개, 유상증자, 무상증자 및 주식배당등의 형태로 이루어진다. 기업공개란 주식회사가 신규발행 주식을 다수의 투자자로부터모집을 하거나 이미 발행되어 대주주 등이 소유하고 있는 주식(구주)을 매출하여 주식을 분산시키는 것을 말하며, 유상증자는 기업재무구조 개선 등을 목적으로 회사가 신주를 발행하여 자본금을 증가시키는 것이다. 무상증자란 주금의 납입 없이 이사회의 결의로 준비금 또는 자산재평가적립금을 자본에 전입하고 전입액만큼 발행한 신주를 기존 주주에게소유 주식수에 비례하여 무상으로 교부하는 것을 말하며, 주식배당이란 현금 대신 주식으로 배당함으로써 이익을 자본으로 전입하는 것을 말한다.', related_words = ARRAY['유통시장']::text[] WHERE id = 227;  -- 발행시장
UPDATE public.words SET meaning = '배당할인모형(Dividend Discount Model)은 주식투자에 따라 발생하는 미래의 현금흐름을 적절한 할인율을 적용하여 현재가치로 전환함으로써 주식의 현재가치를 평가하는 모형이다.', detailed_meaning = '배당할인모형(Dividend Discount Model)은 주식투자에 따라 발생하는 미래의 현금흐름을 적절한 할인율을 적용하여 현재가치로 전환함으로써 주식의 현재가치를 평가하는 모형이다. 주식투자에 따른 현금흐름은 보유기간 중의 배당금과 매도할 경우의 주식가격으로 구성되는데 만일 보유기간이 매우 길다면 매도할 주식가격의 현재가치는 0에 수렴하게 된다. 일반적으로 주식은 만기가 없는 영구적인 증권이므로 보유기간을 무한대로 상정할 수 있다. 따라서 주식의 가치는 각 기별 배당금을 적절한 할인율(주식투자의 요 구수익률이라고 함)로 할인한 현재가치의 합으로 볼 수 있다. 배당할인모형은 주식가치평가모형 중 가장 기본적인 모형으로서 주식가격 형성에 있어서 핵심 요인이 무엇인지를 보여준다. 그러나 기업경영 및 이익에 관한 수많은 불확실성 등으로 인해 먼 미래의 배당금을 추정하는 것은 불가능에 가깝다. 이러한 문제점을 극복하기 위해 Myron Gordon은 배당금이 일정률로 성장한다는 가정을 기초로 정률성장배당할인모형(Constant Growth Dividend Discount Model)을 제시하였다. Gordon의 모형에 따르면 현재 주식의 가치 (P0), 최근 예상배당(D1), 주식투자의 요구수익률(r), 배당성장률(g) 간에는 P0=D1/(r-g) 의 관계가 성립한다. ㅂ', related_words = ARRAY['배당금','할인율']::text[] WHERE id = 231;  -- 배당할인모형
UPDATE public.words SET meaning = '법정화폐(Legal Tender)란 법률에 의해 인정되는 공적 지불수단의 성격을 지닌 화폐를 의미한다.', detailed_meaning = '법정화폐(Legal Tender)란 법률에 의해 인정되는 공적 지불수단의 성격을 지닌 화폐를 의미한다. 다시 말해 국가가 법률로 부채의 상환, 상품 구매, 세금 납부 등에 있어서 반드시 수령하고 경제적 거래가 완결됨을 의미한다. 국가마다 법정화폐로 인정되는 범위가 다 른데 우리나라의 경우 한국은행법 제48조에서 “한국은행이 발행한 한국은행권은 법화(法 貨)로서 모든 거래에 무제한 통용된다.”고 규정함으로써 한국은행권이 모든 경제적 거래에서 법정화폐로 인정된다. 그러나 법정화폐 수령 거부에 대한 처벌 조항이 없는 데다 신용카드, 실시간 계좌이체 등 전자결제 수단에 대한 선호, 큰 금액의 채무를 소액 주화를 대량으로 지급하여 수령인의 불편을 초래하는 행위에 대한 사회적 반감 등으로 한국은행권이 완전한 법정화폐로서 기능하는 데에는 현실적인 한계가 존재한다.', related_words = '{}'::text[] WHERE id = 235;  -- 법정화폐
UPDATE public.words SET meaning = '변동금리란 시장금리를 반영하여 일정 주기별로 약정금리가 변하는 금리를 의미하며, 고 정금리란 최초 약정한 금리가 만기 때까지 그대로 유지되는 금리를 의미한다.', detailed_meaning = '변동금리란 시장금리를 반영하여 일정 주기별로 약정금리가 변하는 금리를 의미하며, 고 정금리란 최초 약정한 금리가 만기 때까지 그대로 유지되는 금리를 의미한다. 예를 들어 만기 1년, 약정금리는 4%의 고정금리라면 약정기간 1년 동안 시장금리가 어떻게 변하더라도 해당 약정금리는 4%이다. 반면 만기 1년, 변동주기 3개월, 약정금리는 CD금리+0.5%(또는 50bp)의 변동금리라면 3개월에 한 번씩 변동된 CD금리에 연동하여 약정금리가 변하게 된다. 예를 들어 CD금리가 최초 약정시 3.0%, 약정 3개월 후 3.2%, 6개월 후 3.5%, 9개월 후 4.0%라면 약정금리는 최초 약정시 3.5%, 약정 3개월 후 3.7%, 6개월 후 4.0%, 9개월 후 4.5%가 된다. 자금 차입자 입장에서는 앞으로 시장금리가 상승할 것으로 예상하는 경우에는 고정금리를 이용하는 것이 유리하고 시장금리가 하락할 것으로 예상하는 경우에는 변동금리를 이용하는 것이 유리하다. 일반적으로 동일 만기에서 는 고정금리가 변동금리보다 높은데 이는 자금 대여자(은행)에게 약정 기간 중 금리 변동에 따른 위험 프리미엄이 존재하기 때문이다. 한편 변동금리의 준거가 되는 금리는 CD금리가 주로 적용되었으나 지금은 COFIX와 은행채 금리도 많이 활용되고 있다.', related_words = ARRAY['고정금리','자금조달비용지수(COFIX)']::text[] WHERE id = 238;  -- 변동금리
UPDATE public.words SET meaning = '보복소비(Revenge Spending 혹은 Pent-up Demand)란 상당 기간 소비 기회가 막혀 강제적으로 소비가 제한되거나 혹은 소비가 억제됨에 따른 피로 누적과 이에 대한 보상욕구,', detailed_meaning = '보복소비(Revenge Spending 혹은 Pent-up Demand)란 상당 기간 소비 기회가 막혀 강제적으로 소비가 제한되거나 혹은 소비가 억제됨에 따른 피로 누적과 이에 대한 보상욕구, 미래 소비기회 상실 우려 등에 대한 반작용으로 소비가 급격하게 늘어나는 것을 의 미한다. 최근 코로나19로 억눌렸던 소비 욕구 및 수요가 보복하듯 한꺼번에 분출하는 현상을 지칭하기 위하여 널리 쓰여지게 되었다. 2020년 중국 언론과 소비 트렌드 분석에서 처음 부각된 것으로 알려져 있다.', related_words = '{}'::text[] WHERE id = 239;  -- 보복소비
UPDATE public.words SET meaning = '국제결제은행(BIS)의 기준에 따른 은행의 자기자본(=기본자본+보완자본)을 구성하는 요 소로서, 기본자본에 비해 손실흡수능력이 떨어지지만 예상외 손실로 은행이 파산할 경우예금자를 포함한', detailed_meaning = '국제결제은행(BIS)의 기준에 따른 은행의 자기자본(=기본자본+보완자본)을 구성하는 요 소로서, 기본자본에 비해 손실흡수능력이 떨어지지만 예상외 손실로 은행이 파산할 경우예금자를 포함한 일반채권자에 앞서 손실을 흡수(혹은 은행의 청산 시 은행의 손실을 보전)할 수 있는 자기자본(gone-concern capital)을 의미한다. 보완자본은 해당하는 요건 ㅂ을 충족하는 보완자본증권 및 이와 관련된 자본잉여금, 자회사가 발행한 보완자본증권의 일부 제3자 보유분, 특정 요건을 충족하는 대손충당금 등으로 구성된다. 해당 은행이 발행한 증권이 보완자본증권으로 인정받기 위해서는 예금자·일반채권자보다 후순위일 것,최저만기 5년 이상이고 금리 상향조정을 비롯한 중도상환 유인이 없을 것 등의 요건을 충족해야 한다(참고 「은행업감독업무시행세칙」별표 3). 아울러 신용리스크 측정시 표준방법을 사용하는 은행이 설정한 일반 대손충당금(general provisions)과 내부등급법 사용은행이 예상손실을 초과하여 적립한 적격 대손충당금은 규제자본과 동일하게 예상외 손실을 흡수하는 데 사용할 수 있다고 간주하여 일정 범위(각각 신용위험가중자산의 1.25% 및 0.6%) 내에서 보완자본(supplementary capital)에 가산할 수 있다.', related_words = ARRAY['BIS 자기자본비율','기본자본(Tier 1)']::text[] WHERE id = 240;  -- 보완자본(Tier 2)
UPDATE public.words SET meaning = '보통주자본(CET1; Common Equity Tier 1)은 바젤Ⅲ 자본규제에서 기본자본(Tier 1)을 구성하는 핵심 요소로서, 손실흡수능력이 가장 높은(혹은 은행의 손실을 가장 먼저 보전할', detailed_meaning = '보통주자본(CET1; Common Equity Tier 1)은 바젤Ⅲ 자본규제에서 기본자본(Tier 1)을 구성하는 핵심 요소로서, 손실흡수능력이 가장 높은(혹은 은행의 손실을 가장 먼저 보전할 수 있는) 자본을 의미하며 보통주 발행으로 인한 자본금·자본잉여금, 이익잉여금, 기타포괄손익누계액 등으로 구성된다. 특정 자본이 보통주자본으로 인정받기 위해서는 청산시 최후 순위일 것, 영구적일 것, 청산시를 제외하고는 상환불가, 재매입 및 상환 또는 발행취소에 대한 기대가 없을 것 등의 요건을 충족해야 한다(참고 「은행업감독업무시행세칙」별표 3). 바젤Ⅲ에서는 보통주자본비율을 위험가중자산의 4.5% 이상이 되도록 규정하고 있다.', related_words = ARRAY['기본자본(Tier 1)','기타기본자본(Additional Tier 1)']::text[] WHERE id = 242;  -- 보통주자본(Common Equity Tier 1)
UPDATE public.words SET meaning = '보호무역주의는 국가간 무역을 제한하는 경제정책이다.', detailed_meaning = '보호무역주의는 국가간 무역을 제한하는 경제정책이다. 주된 수단으로는 수입금지나 수입할당과 같은 직접적인 방법과 수입상품에 대한 관세 부과와 같은 간접적인 방법 이외에도 덤핑 규제, 보조금 지급, 지적재산권 보호 강화, 환율조작 등 기타 다양한 정부의 규제 등이 있다. 보호무역주의의 목적은 수입으로 경쟁이 유발되는 산업의 생산, 유통, 고용 등에 손해가 발생하지 않도록 하는 것이다. 한편 보호무역주의는 상대국 수출부문의 생산, 고용은 물론 동 정책을 실행하는 국가의 소비자에게도 물가 상승과 같은 부정적 영향을 미친다. 보호무역주의의 순효과는 경제의 성장이나 발전에 부정적이라는 견해가 지배적이어서 선진국의 주도하에 세계적으로 무역장벽을 낮추는 추세를 보여 왔다. 그러나 일부에서 무역수지 흑자국과 적자국이 뚜렷이 구분·지속되고 수지폭도 점점 커지면서 단기적으로 적자국 수입경쟁 부문의 고용이 심각한 불균형을 보이는 등 부작용도 확대되었다. 이러한 부작용은 특히 2008년 발생한 글로벌 금융위기의 한 원인으로 지적되기도 했 다. 최근 미국이 보호무역을 강화하는 정책을 실시하면서 무역갈등이 심화되고 있으나 G20의 대부분 국가는 보호무역주의의 확산을 경계하고 있다.', related_words = ARRAY['긴급수입제한조치']::text[] WHERE id = 244;  -- 보호무역주의
UPDATE public.words SET meaning = '복수통화바스켓제도란 자국과 교역 비중이 큰 복수국가의 통화를 선택하여 통화군(바스켓)을 구성하고 바스켓(basket)을 구성하는 통화들의 가치가 변동할 경우 각 통화별 교역가중치에 따라 자국통화의', detailed_meaning = '복수통화바스켓제도란 자국과 교역 비중이 큰 복수국가의 통화를 선택하여 통화군(바스켓)을 구성하고 바스켓(basket)을 구성하는 통화들의 가치가 변동할 경우 각 통화별 교역가중치에 따라 자국통화의 환율에 반영하는 환율제도를 말한다. 복수통화바스켓제도 는 자국 통화의 가치가 달러화 같은 특정 외국 통화에 고정되는 것이 아니라 바스켓에 포함된 여러 통화의 가치 변화에 따라 변동하게 하여 환율의 안정성을 도모하는 동시에 환율이 주요 교역상대국과의 경쟁력을 종합적으로 반영하게 하는 장점이 있다. 우리나라는 1980년 2월부터 복수통화바스켓제도를 시행한 바 있으며, 당시 원/달러 환율은 SDR의 대미달러화 환율인 SDR바스켓과 우리나라의 주요 교역상대국인 미국, 일본, 서독, 영국, 프랑스 통화의 미달러화에 대한 환율변동을 가중평균한 독자바스켓, 그리고 정책조정변수인 실세반영장치의 세 가지 요소에 의해 결정되었다. 이후 점차 정책당국의 영향력 때문에 환율이 외환 수급을 적절히 반영하지 못할 수 있다는 우려가 커짐에 따라, 1990년 3 월 정부는 환율 결정에 시장 원리를 보다 폭넓게 반영하기 위하여 시장평균환율제도로 이 행하였다.', related_words = ARRAY['고정환율제도/자유변동환율제도','미달러화페그제도']::text[] WHERE id = 245;  -- 복수통화바스켓제도
UPDATE public.words SET meaning = '제도단위(비금융법인, 금융법인, 일반정부, 가계 및 비영리단체)가 생산과정에 참여하거나 생산활동에 제공된 자산을 소유함에 따라 발생하는 소득으로 국민순소득(NNI; Net National', detailed_meaning = '제도단위(비금융법인, 금융법인, 일반정부, 가계 및 비영리단체)가 생산과정에 참여하거나 생산활동에 제공된 자산을 소유함에 따라 발생하는 소득으로 국민순소득(NNI; Net National Income)이라고도 한다. 이는 생산에 의해 창출된 부가가치에서 지급된다. 구체적으로 본원소득은 피용자보수에 영업잉여, 순생산 및 수입세, 순수취재산소득을 더하여 계산한다. 본원소득 = 피용자보수 + 영업잉여 + 순생산 및 수입세 + 순수취재산소득', related_words = ARRAY['영업잉여','피용자보수']::text[] WHERE id = 247;  -- 본원소득
UPDATE public.words SET meaning = '본원소득수지는 급료 및 임금 수지와 투자소득수지로 구분된다.', detailed_meaning = '본원소득수지는 급료 및 임금 수지와 투자소득수지로 구분된다. 급료 및 임금 수지는 외국인 근로자에게 지급되거나 내국인 해외근로자가 수취하는 금액의 차이를 의미한다. 투자소득수지는 대외 금융자산과 부채의 보유에 의해 발생하는 배당금과 이자 등의 수입과 지급의 차이를 말하는데, 투자 형태에 따라 직접투자소득, 증권투자소득, 기타투자소득으로 세분된다.', related_words = ARRAY['본원소득']::text[] WHERE id = 248;  -- 본원소득수지
UPDATE public.words SET meaning = '증권의 부동화(Immobilization)란 실물증권을 중앙예탁기관에 집중 보관하여 매매거래 또는 담보거래 등에 따른 증권의 권리이전을 계좌대체 방식으로 처리함으로써 증권의 실물인도의 필요성을', detailed_meaning = '증권의 부동화(Immobilization)란 실물증권을 중앙예탁기관에 집중 보관하여 매매거래 또는 담보거래 등에 따른 증권의 권리이전을 계좌대체 방식으로 처리함으로써 증권의 실물인도의 필요성을 제거하는 것을 말한다. 증권실물은 이동하지 않고 예탁기관의 장부상 대차기재에 의하여 증권에 대한 권리가 이전됨으로써 실물증권 이동에 따른 분실· 도난의 위험성, 사무처리의 번잡성 등의 문제점을 해결할 수 있다. 한편 증권의 무권화(Dematerialization)란 유가증권에 대한 권리를 표시하는 실물증권을 발행하지 않고 증권에 대한 권리가 오로지 장부(발행기관 및 중앙예탁기관의 계좌)상에 전자기록 형태로 존재하도록 하여 신주발행 및 증권유통에 따른 권리를 이전하는 것을 말한다.', related_words = ARRAY['중앙예탁기관']::text[] WHERE id = 252;  -- 부동화/무권화
UPDATE public.words SET meaning = 'CDO(Collateralized Debt Obligation)란 회사채나 대출채권 등으로 구성된 pool을 기초자산으로 하여 AAA등급에서 equity(non-rated)까지의 다양한', detailed_meaning = 'CDO(Collateralized Debt Obligation)란 회사채나 대출채권 등으로 구성된 pool을 기초자산으로 하여 AAA등급에서 equity(non-rated)까지의 다양한 신용등급으로 발행된 여러 종의 선·후순위 채권을 말하며, 기초자산의 종류에 따라 회사채를 기초자산으로 하는 회사채 담보부증권(CBO; Collateralized Bond Obligation), 대출채권을 기초자산으로 하는 대출채권 담보부증권(CLO; Collateralized Loan Obligation)으로 분류된다. 그리고 발행목적에 따라 주로 은행 등의 금융기관이 재무상태표상에서 위험자산을 제거하기 위하여 발행하는 Balance Sheet CDO와 고수익의 원자산인 대출금, 회사채 등과 선· 후순위 채권 간의 이자차익을 얻기 위해 발행하는 Arbitrage CDO 등이 있다. 미국의 모기지 전문 대출기관들은 2000년대 초중반 부동산 활황을 틈타 대출자금을 조달하기 위하여 모기지 채권이나 주택저당증권(MBS)을 대량으로 발행하였고, 투자은행들이 이를 사들여 합성한 뒤 발행한 채권이 바로 CDO였다. 2007년 주택담보대출 연체율이 높아지면서 이른바 서브프라임 모기지론 사태가 벌어져 채권 가격이 폭락함으로써 주요 금융회사 등 ㅂ 투자자들이 큰 손실을 입고 글로벌 금융위기로 이어지게 되었다.', related_words = ARRAY['CMO']::text[] WHERE id = 254;  -- 부채담보부증권(CDO)
UPDATE public.words SET meaning = '부채를 자기자본으로 나눈 비율로 대표적인 안정성 지표이다.', detailed_meaning = '부채를 자기자본으로 나눈 비율로 대표적인 안정성 지표이다. 이 비율이 낮을수록 재무구조가 건전하다고 판단할 수 있다. 부채비율은 자기자본비율과 역(逆)의 관계에 있어 자기자본비율이 높을수록 부채비율은 낮아지게 된다. 부채에는 차입금, 회사채, 매입채무, 미지급금, 부채성충당금 등이 포함되며, 지급기일 도래 시점에 따라 1년 이내에 지급기일이 도래하는 유동부채, 1년 이후에 지급기일이 도래하는 비유동부채로 분류할 수 있다. 경영자 입장에서는 단기채무 상환의 압박을 받지 않고 투자수익률이 차입금리 등의 조달금리를 상회하는 한 타인자본을 계속 이용하는 것이 유리하다. 그러나 부채비율이 높은 기업은 상대적으로 경기나 금리변동에 취약하다. 현금흐름이 악화되거나 금리가 상승하면 이 자 부담이 커지고 원리금 상환이 어려워질 가능성이 커지기 때문이다. 부채비율 = [(유동부채 + 비유동부채)/자기자본] × 100', related_words = '{}'::text[] WHERE id = 255;  -- 부채비율
UPDATE public.words SET meaning = '분산원장기술(DLT; Distributed Ledger Technology)은 거래정보가 기록된 원장을 특정 기관의 중앙 서버가 아닌 공유(P2P; Peer-to-Peer) 네트워크에 분산하여', detailed_meaning = '분산원장기술(DLT; Distributed Ledger Technology)은 거래정보가 기록된 원장을 특정 기관의 중앙 서버가 아닌 공유(P2P; Peer-to-Peer) 네트워크에 분산하여 다수의 참가 자가 공동으로 기록·관리하는 기술이다. 전통적 금융시스템의 근간을 이루고 있는 중앙집중형(centralized) 시스템은 원장을 집중·관리하는 ‘제3의 기관’(TTP; Trusted Third Party)을 설립하고 해당 기관에 대한 신뢰를 확보하는 방식으로 발전해 왔다. 예컨대 투자자들이 증권회사를 통해 거래하는 주식을 집중·관리하는 ‘한국예탁결제원’(KSD)이 곧제3의 기관이다. 반면 분산원장기술에서는 다수 참여자가 거래내역이 기록된 원장 전체를 각각 분산 보관(decentralized)하고, 거래할 때마다 이를 검증하며 갱신하는 작업을 공동으로 수행한다. 분산원장기술은 가상자산 발행처럼 누구나 접근 가능하고 거래의 기록 및 관리에도 참여할 수 있는 개방형·비허가형(public, permissionless)과 기업내부또는 금융회사간 시스템처럼 허가받은 경우에만 접근할 수 있는 폐쇄형·허가형(private, permissioned)으로 나눌 수 있다. 분산원장기술은 당초 비트코인·이더리움 등 가상자산(virtual asset)의 기반 기술로 개발되었으나, 현재는 동 기술을 다양한 금융서비스에 활용하기 위한 방안을 모색중이다.', related_words = ARRAY['P2P대출','블록체인','비트코인','가상자산']::text[] WHERE id = 257;  -- 분산원장기술
UPDATE public.words SET meaning = '분수효과(Trickle-up Effect, Fountain Effect)란 정부가 경제정책으로 저소득층과 중산층의 소득을 먼저 늘려주면 이들의 소비 확대가 생산과 투자로 이어지면서 전체 경제활동이', detailed_meaning = '분수효과(Trickle-up Effect, Fountain Effect)란 정부가 경제정책으로 저소득층과 중산층의 소득을 먼저 늘려주면 이들의 소비 확대가 생산과 투자로 이어지면서 전체 경제활동이 되살아나고 이로 인해 고소득층의 소득도 늘어날 수 있다는 주장이다. 즉 분수에서 물이 아래에서 위로 솟아나는 것처럼 저소득층에서 시작된 소득과 소비 증대의 효과가 점차상위 계층으로 확산되면서 전체 경제도 좋아질 수 있다는 것이다. 이러한 주장은 영국의 경제학자인 케인즈(J. M. Keynes)가 경제 활성화에 긴요한 총수요 진작을 위해서는 상대적으로 한계소비성향이 높은 저소득층과 중산층에 초점을 맞추어 정부지출을 늘리고 세금을 줄여야 한다는 논리에 근거하고 있다. 이는 분배보다는 성장에, 그리고 저소득층보다는 고소득층에 중점을 두어 경제정책을 운용해야 한다는 낙수효과와는 상반되는 개념이다. ㅂ', related_words = ARRAY['낙수효과']::text[] WHERE id = 258;  -- 분수효과
UPDATE public.words SET meaning = '브레튼우즈체제는 1944년 7월 미국의 뉴햄프셔주 브레튼우즈에서 44개 연합국 대표들이 새로운 국제통화제도 구축을 위해 체결한 협정에 따라 발족한 국제통화체제를 말한다.', detailed_meaning = '브레튼우즈체제는 1944년 7월 미국의 뉴햄프셔주 브레튼우즈에서 44개 연합국 대표들이 새로운 국제통화제도 구축을 위해 체결한 협정에 따라 발족한 국제통화체제를 말한다. 이 협정을 체결하게 된 배경은 1930년대 대공황의 여파로 인한 금본위제도 붕괴, 무역규제 확대, 환율 불안정에 이어 1940년대 국제유동성 부족, 외환규제 확산 등으로 국제통화질서가 위기에 직면하게 되었기 때문이다. 브레튼우즈체제는 국제통화제도의 본질적인 기능인 유동성 공급과 국제수지 조정 메커니즘을 미달러화를 기축통화로 하는 금환본위제도와 조정가능 고정환율제도를 통해서 해결하고자 하였다. 즉 각국은 달러를 대외준비자산으로 보유하고 미국은 다른 나라가 보유한 달러에 대해 금태환을 보장하며, 각국의 고정환율에 조정이 필요한 경우 국제통화기금(IMF)과 협의하여 변경할 수 있도록 하였다. 이를 뒷받침하기 위하여 설립된 국제기구가 IMF와 국제부흥개발은행(IBRD)이다. 1960년대 들어 국제유동성 수준이 미국의 국제수지 상태에 따라 결정되고 환율 변경을 통한 불균형 개선이 쉽지 않은 등의 구조적인 문제가 대두되는 가운데 1971년 미국이 달러화의 금태환을 정지하고 뒤이어 선진국들이 변동환율제도로 이행함에 따라 브레튼우즈체제는 사실상 붕괴되었다. ㅂ', related_words = ARRAY['국제통화기금(IMF)','금본위제','고정환율제도/자유변동환율제도']::text[] WHERE id = 261;  -- 브레튼우즈체제
UPDATE public.words SET meaning = '브렉시트(Brexit)는 영국(Britain)과 탈퇴(Exit)의 합성어로 영국의 유럽연합(EU) 탈퇴를 뜻한다.', detailed_meaning = '브렉시트(Brexit)는 영국(Britain)과 탈퇴(Exit)의 합성어로 영국의 유럽연합(EU) 탈퇴를 뜻한다. 영국은 2016년 6월 23일 유럽연합(EU) 탈퇴 여부에 대한 국민투표 실시를 통해 51.9%의 찬성으로 EU 탈퇴를 결정하였다. 영국 국민들이 EU 탈퇴를 찬성하게 된 배경에는 2008년 글로벌 금융위기 이후 남유럽국가 구제금융 지원, EU의 난민 포용정책 등 으로 영국의 재정부담이 가중되는 가운데 회원국 노동자의 영국 이주에 따라 영국 고용시장이 악화되는 데 대한 불만이 크게 작용하였다. 2017년 3월 영국 정부가 EU 정상회의 (European Council)에 탈퇴 의사를 공식 통보함으로써 탈퇴 협상이 개시되었으며 이후양자간 긴 협상 끝에 2020년 12월 말 공식적인 탈퇴 절차가 완료되었다. 브렉시트 이후수년간 영국 경제는 여러 가지 부정적인 영향을 받았다. 영국의 대EU 수출은 감소한 반면수입은 증가하여 무역적자가 확대되었고, 저임금 이민 노동자 감소로 인한 노동인력 부족과 비EU 이민자 증가 등이 경제·사회적 문제로 대두되고 있다. 이에 따라 브렉시트에 대한 회의적 시각이 커지게 되었다.', related_words = ARRAY['유럽연합(EU)']::text[] WHERE id = 262;  -- 브렉시트(Brexit)
UPDATE public.words SET meaning = '개인이나 기업이 주택구입, 대규모 개발 프로젝트 수행 등을 위해 장기 자금조달이 필요 할 경우, 해당 자금 마련 이전에 일시적으로 소요되는 비용을 충당하기 위해 단기 자금조달 수단으로 이용하는', detailed_meaning = '개인이나 기업이 주택구입, 대규모 개발 프로젝트 수행 등을 위해 장기 자금조달이 필요 할 경우, 해당 자금 마련 이전에 일시적으로 소요되는 비용을 충당하기 위해 단기 자금조달 수단으로 이용하는 것이 브릿지론이다. 마치 다리(bridge) 역할을 하는 자금조달 수단이다. 예를 들어 부동산 개발 사업을 실시할 경우 토지를 매입하는 초기 단계에서 이에 필요한 자금을 본격적인 PF(Project Financing) 대출로 전환되기 이전에 일시적으로 조달하는 용도로 사용된다. 브릿지론은 일반적으로 6개월에서 1년 만기 정도의 단기대출이며 본 PF대출에 비해 금리가 높다. 이는 초기 사업비용 충당이 주목적인 브릿지론의 특성을 감안할 때 리스크가 높은 점이 반영된 것이다.', related_words = '{}'::text[] WHERE id = 264;  -- 브릿지론
UPDATE public.words SET meaning = '비관측경제(NOE; Non-observed Economy)란 국내총생산(GDP)의 추계에 이용되는 기초자료와 행정자료에 누락된 경제활동을 의미한다.', detailed_meaning = '비관측경제(NOE; Non-observed Economy)란 국내총생산(GDP)의 추계에 이용되는 기초자료와 행정자료에 누락된 경제활동을 의미한다. GDP는 원칙적으로 합법적이건 불법적이건 모든 경제적 거래에서 발생한 소득을 포함해야 하나 현실적으로 지하경제나 불법생산 등은 반영하기가 쉽지 않다. 비관측경제는 일반적으로 문제영역(problem areas)에 속하는 활동 때문에 발생한다. 대표적인 경우가 흔히 지하경제(underground economy) 나 은닉경제(hidden economy)로 표현되는 경제활동이다. 이는 조세나 사회적 의무의 회피, 근로안전이나 소비자보호 등 법적·행정적 규제에 따른 비용의 회피를 위하여 은밀하게 이루어진다. 이러한 거래는 세무·통계 당국에 축소 보고되기도 하고 현금거래로만 행해져 아예 누락되기도 한다. 또한 마약, 장물 거래, 성매매 등과 같이 생산물의 내용이 불법적인 경우도 거래내역을 포착하기 힘들다. 불법생산(illegal production)은 판매나 소유 자체가 법에 의해 금지되어 있으나 GDP에는 포함되어야 한다는 것이 국제적으로 합의된 원칙이다. 이 밖에도 “통계적 지하(statistical underground)”라고 불리는 소규모기업이나 자영업자 등에 대한 미흡한 기초통계 자료 등에 의해서도 비관측경제가 존재하게 된다.', related_words = ARRAY['국내총생산(GDP)']::text[] WHERE id = 265;  -- 비관측경제(NOE)
UPDATE public.words SET meaning = '재화나 서비스의 생산과 관련하여 투입요소 비용의 상승에 의해 물가가 지속적으로 오르게 되는 것을 비용인상 인플레이션(Cost-Push Inflation)이라고 한다.', detailed_meaning = '재화나 서비스의 생산과 관련하여 투입요소 비용의 상승에 의해 물가가 지속적으로 오르게 되는 것을 비용인상 인플레이션(Cost-Push Inflation)이라고 한다. 주요 투입요소인 노동, 자본, 원자재 등의 가격이 상승하면 기업은 증가한 생산비용을 가격에 반영시키므로 최종재의 가격이 오르게 되는 것이다. 비용인상 인플레이션은 경제 내의 생산활동을 위축시키면서 유발되므로 사람들의 소득 수준이 악화될 가능성이 크다. 실제로 1970 년대 발생한 2차례의 오일쇼크(석유가격이 급등하여 재화 및 서비스의 생산비가 크게상승했음)로 인해 유발된 비용인상 인플레이션은 이러한 가능성을 보여주고 있다. 당시유가 상승으로 인해 생산비가 증가하면서 생산활동이 위축되고 이로 인해 경기가 둔화되었다.', related_words = ARRAY['수요견인 인플레이션']::text[] WHERE id = 267;  -- 비용인상 인플레이션
UPDATE public.words SET meaning = '비트코인(Bitcoin)은 가상통화(암호통화)이자 디지털 지급시스템 전자 토큰 형태의 가상자산이다.', detailed_meaning = '비트코인(Bitcoin)은 가상통화(암호통화)이자 디지털 지급시스템 전자 토큰 형태의 가상자산이다. 비트코인 시스템은 중앙 저장소 또는 단일 관리자 없이 탈중앙화된 구조로 작동한다. 비트코인은 사토시 나카모토라는 사람(집단)에 의해 만들어진 것으로 알려져 있고 2009년 개방형 소프트웨어로 배포되었다. 이 시스템은 공유형(peer-to-peer)이며, 거래는 중개자 없이 블록체인 소프트웨어를 이용하는 참여자(nodes) 사이에 직접 이뤄진다. 이런 거래들은 공유(P2P) 네트워크상 참여자의 작업증명(proof-of-work)을 통해 검 증되고 공개된 분산원장인 블록체인에 기록된다. 승인된 거래의 새 그룹인 한 블록은 대략 10분에 한 번씩 만들어져서 블록체인에 추가되고 신속하게 모든 참여자에게 보내진다. 비트코인은 컴퓨터 처리 능력(power)을 활용해서 이뤄지는 채굴(mining)에 대한 보상으로 발행되고 있으며, 비트코인을 다른 통화·상품·용역 등과 교환하는 거래도 발생하고 있다. 중앙은행이 발행한 법정화폐가 아닌 비트코인은 비트코인플랫폼에서 거래되며 투자대상으로도 많은 관심을 받고 있다. 또한 익명성으로 자금세탁 등 불법거래에 악용될소지가 많아 일부 국가에서 비트코인 등 가상통화의 거래를 규제하기도 한다. 일본의 경우 비트코인의 거래이익에 대해 세금을 부과한다. 비트코인은 추가되는 한 블록당 새로 6.25비트코인을 보상하는데(2020.5월 기준), 21만개가 채굴될 때(대략 4년)마다 그 보상이 반으로 줄어든다. 비트코인의 총량은 21백만개이며 2140년경 모두 채굴될 것으로 전망된다. 비트코인은 그 시스템의 설계시 그 수량을 한정시켜 놓았기 때문에 원칙적으로 인플레이션에 의해 가치가 떨어질 수 있는 화폐와 다른 속성을 지닌다. 한편 2017년에는 비트코인에서 규칙을 근본적으로 바꾸는 하드포크(hard-fork)가 발생하였고, 이 과정에 서 8월 1일에는 ‘비트코인캐시(BCH)’가, 10월 25일에는 ‘비트코인골드(BTG)’가 새롭게만들어져 기존 비트코인(classic bitcoin)과는 별도로 거래되고 있다.', related_words = ARRAY['가상자산','작업증명','블록체인']::text[] WHERE id = 268;  -- 비트코인
UPDATE public.words SET meaning = '빅맥지수(Big Mac Index)는 각국 통화의 구매력 정도 또는 환율 수준을 측정하기 위해일물일가의 법칙을 햄버거 가격에 적용한 것으로 영국에서 발행되는 주간 경제전문지 이 코노미스트지(The', detailed_meaning = '빅맥지수(Big Mac Index)는 각국 통화의 구매력 정도 또는 환율 수준을 측정하기 위해일물일가의 법칙을 햄버거 가격에 적용한 것으로 영국에서 발행되는 주간 경제전문지 이 코노미스트지(The Economist)에서 1986년 이래 매년 전 세계적으로 판매되고 있는 맥도날드의 빅맥 가격을 비교·분석해서 발표하고 있다. 맥도날도의 빅맥은 전 세계 120개국에서 동일한 재화로 판매되고 있으므로, 이 빅맥지수를 이용하여 일물일가의 법칙 또는 절대적 구매력평가를 간단하게 검증할 수 있는 기회를 독자들에게 제공한다는 취지이 다. 만약 일물일가의 법칙이 완전하게 성립한다면 세계 모든 나라에서 빅맥의 미달러화가격이 동일하여야 하므로 실제 환율과는 다른 구매력평가환율을 산정해 볼 수 있다. 예를 들어 어느 기준시점의 우리나라 빅맥 가격이 5,500원이고 미국에서의 가격은 5.69달러라 하면, 구매력평가이론의 일물일가의 법칙이 성립한다면 원/달러 환율은 967원/달러(=5,500원/5.69달러)가 되어야 한다. 그런데 그 시점의 실제 환율이 1,350원/달러라면빅맥지수로 볼 때 원화는 미달러화 대비 약 28% 저평가되어 있다고 볼 수 있다.', related_words = ARRAY['구매력평가환율','일물일가의 법칙']::text[] WHERE id = 270;  -- 빅맥지수
UPDATE public.words SET meaning = '현재 비어있거나 1개월 안에 새로 채용될 수 있는 일자리 수를 전체 근로자 수와 빈 일자리수의 합으로 나눈 백분율을 의미한다.', detailed_meaning = '현재 비어있거나 1개월 안에 새로 채용될 수 있는 일자리 수를 전체 근로자 수와 빈 일자리수의 합으로 나눈 백분율을 의미한다. 우리나라에서는 고용노동부가 매달 발표하고 있다.', related_words = ARRAY['베버리지 곡선']::text[] WHERE id = 271;  -- 빈일자리율
UPDATE public.words SET meaning = '정보통신기술의 발달로 기업경영활동에서 디지털화가 가속화되고 상호 연결이 확대되어감에 따라 전자상거래나 정보통신기술을 이용하여 이루어지는 활동 중 사이버 상에서 발생하는 예기치 못한 사고로 인해', detailed_meaning = '정보통신기술의 발달로 기업경영활동에서 디지털화가 가속화되고 상호 연결이 확대되어감에 따라 전자상거래나 정보통신기술을 이용하여 이루어지는 활동 중 사이버 상에서 발생하는 예기치 못한 사고로 인해 기업이 부담하게 될 유·무형의 비용이 증가하는 위험을 말한다. 사이버리스크 발생에 따른 유형의 비용에는 자금 분실, 컴퓨터시스템 손상 또는 악성코드 감염, 네트워크 폐쇄에 따른 조업중단, 고객정보 및 디지털자산의 분실, 정보유출에 따른 법적 및 피해자 보상 등이 있으며, 무형의 비용으로는 고객 이탈, 기업 신뢰도 하락, 브랜드 이미지 손상, 핵심기술 유출에 따른 경쟁우위 훼손 등이 있다. 사이버리스크에 대한 대책으로는 사전 대응(secure)과 지속적 경계(vigilant) 및 신속한 복구능력(resilient) 확보가 제시되고 있다. 한편 디지털 정보량의 증대와 클라우드 컴퓨팅 이용 기업의 증가세를 감안할 때 향후 사이버리스크에 대한 노출은 더욱 늘어날 것으로 예상된다.', related_words = '{}'::text[] WHERE id = 273;  -- 사이버리스크
UPDATE public.words SET meaning = '사전적 정책방향 제시는 향후 통화정책 방향에 대해 중앙은행이 명시적으로 시그널을 전달하는 것으로 새로운 정책은 아니다.', detailed_meaning = '사전적 정책방향 제시는 향후 통화정책 방향에 대해 중앙은행이 명시적으로 시그널을 전달하는 것으로 새로운 정책은 아니다. 그러나 글로벌 금융위기 이후 정책금리의 추가 인하가 어렵고 경제여건의 불확실성이 높은 상황에서 주요국 중앙은행이 적극적으로 그 방식을 다양화하여 활용하였다는 점에서 비전통적 통화정책의 일종으로 분류되고 있다. 중앙은행이 정책금리를 상당 기간 낮은 수준으로 유지할 것이라는 사전적 정책방향을 명확히 제시할 경우 단기시장금리의 미래 기대경로를 낮추고 정책금리 경로 관련 불확실성이 줄어들어 기간프리미엄도 축소되면서 장기금리의 하락에 기여할 수 있다. 또한 중앙은 행이 당면한 정책목표 간의 상충관계에 대한 견해를 제시하여 정책목표의 우선순위를 명확히 전달할 수도 있다. 사전적 정책방향 제시는 미래에 대한 예고이기 때문에 정책적으로 유효하기 위해서는 경제주체들의 중앙은행에 대한 신뢰가 긴요하다. 경제·금융 여건이 예상과 다르게 변화하여 중앙은행이 당초 공표한 정책방향을 변경하게 되면 상황에 따라서는 금융시장의 변동성이 오히려 확대되고 중앙은행의 신뢰성에 부정적인 영향을 줄 가 능성이 있다. 또한 사전적 정책방향의 제시내용이 지나치게 복잡하고 이해하기 어려울 경우 오히려 정책운영 방식의 명료성을 제약하고 정책 불확실성이 다시 높아지는 문제가 발생할 수도 있다.', related_words = ARRAY['양적완화정책','제로금리정책','통화정책 커뮤니케이션']::text[] WHERE id = 274;  -- 사전적 정책방향 제시 (Forward Guidance)
UPDATE public.words SET meaning = '상계관세(Countervailing Duties)는 수출국이 수출기업에 보조금이나 장려금을 지급하여지나치게 낮은 가격을 책정할 경우 수입국이 이로 인한 경쟁력 저하를 상쇄하기 위해 부과 하는', detailed_meaning = '상계관세(Countervailing Duties)는 수출국이 수출기업에 보조금이나 장려금을 지급하여지나치게 낮은 가격을 책정할 경우 수입국이 이로 인한 경쟁력 저하를 상쇄하기 위해 부과 하는 관세를 말한다. 즉 수출국 정부의 보조를 받아 가격·품질 면에서 우위를 갖게 된 수입품으로 인해 수입국이 피해를 입거나 피해를 입을 우려가 있는 경우 그 효과를 상쇄할 목적으로 정규관세 이외에 부과하게 된다. 이러한 점에서 상계관세는 수입국 산업의 경쟁력을 유지하기 위한 일종의 차별관세라 할 수 있다. 우리나라에서는 관세법 제57조에 국내산업을 보호할 필요가 있다고 인정되는 경우 상계관세를 부과할 수 있다고 규정하고 있다.', related_words = ARRAY['긴급수입제한조치']::text[] WHERE id = 279;  -- 상계관세
UPDATE public.words SET meaning = '1989년 7월 설립된 상품공동기금(CFC; Common Fund for Commodities)은 1차산품의 수급 안정을 위한 국제협력 증진과 국제상품협정 체결 촉진 및 기능 활성화를 목적으로', detailed_meaning = '1989년 7월 설립된 상품공동기금(CFC; Common Fund for Commodities)은 1차산품의 수급 안정을 위한 국제협력 증진과 국제상품협정 체결 촉진 및 기능 활성화를 목적으로 하고 있다. 주요 기능으로는 국제상품협정에 따른 완충재고 유지를 위한 금융지원, 1차산품의 개발 촉진 및 교역조건 개선을 위한 연구개발 지원, 1차산품에 관한 가맹국 간정보교환 및 정책협의 촉진 등을 들 수 있다. 2021년 말 기준 가맹국은 101개국과 9개 기구(EC, AU, COMESA 등)로 납입자본금은 139.5백만 달러(약정액 기준)이며 출연금은 175.4백만 달러이다. 우리나라는 1989년 7월 설립과 함께 가입하였으며 2021년 말 기준 1,051.8천 달러를 출자하였다.', related_words = ARRAY['세계무역기구(WTO)']::text[] WHERE id = 281;  -- 상품공동기금(CFC)
UPDATE public.words SET meaning = '국내생산자가 국내시장에 공급하는 상품과 서비스의 평균적인 가격변동을 측정하기 위하여 작성되는 물가지수로서 그 대상품목의 포괄범위가 넓어 전반적인 상품과 서비스의 수급 동향이 반영된 일반적인', detailed_meaning = '국내생산자가 국내시장에 공급하는 상품과 서비스의 평균적인 가격변동을 측정하기 위하여 작성되는 물가지수로서 그 대상품목의 포괄범위가 넓어 전반적인 상품과 서비스의 수급 동향이 반영된 일반적인 물가수준의 변동을 측정할 수 있기 때문에 일반목적지수로서 의 성격을 갖는다. 지수작성에 이용되는 가격은 생산자가 제품 한 단위당 실제로 수취하는 기초가격(basic price)이다. 생산자물가지수는 1910년부터 한국은행에서 작성해 오고 있다.', related_words = ARRAY['소비자물가지수(CPI)','기초가격']::text[] WHERE id = 286;  -- 생산자물가지수(PPI)
UPDATE public.words SET meaning = '인공지능, 소위 AI(Artificial Intelligence)는 인간의 학습, 추론, 문제해결, 지각, 의사결정 등 능력을 인공적으로 구현하는 컴퓨터과학의 한 분야로 인간의 지능을 컴퓨터를', detailed_meaning = '인공지능, 소위 AI(Artificial Intelligence)는 인간의 학습, 추론, 문제해결, 지각, 의사결정 등 능력을 인공적으로 구현하는 컴퓨터과학의 한 분야로 인간의 지능을 컴퓨터를 비롯한 여러 장치에 적용한다. 웹검색 기능, 개인비서 서비스, 자율주행장비 등으로 나타나 고 있다. AI는 1956년 미국 다트머스(Dartmouth) 회의에서 등장한 용어로 학문적 과정의 하나로 시작되었으나 이후 과잉기대, 자금조달 문제 등으로 부침을 겪었다. 2020년대 들어 생성형(generative) AI가 발전하면서 AI 붐이 형성되었다. 생성형 AI는 텍스트, 이미지, 음악, 코드 등 새로운 콘텐츠를 생성하는 AI 기술로 기존 AI가 데이터를 분석하거나 분류하는데 중점을 둔 것과 차이가 있다. GPT, DALL-E, Sora 등이 대표적이며 교육, 의 료, 마케팅, 대고객서비스, 개발 및 연구 분야에서 널리 활용되고 있다. 생성형 AI의 대두는 허위정보 생산, 콘텐츠 조작, 사이버 범죄, 저작권 문제 등 의도하지 않은 결과와 피해를 초래하기도 하였다. 생성형 AI가 인류에 미칠 장기적 효과, 잠재적 능력에 대한 고찰이 진행되면서 도덕적 문제를 포함한 여러 쟁점이 제기되었으며 혜택 확대와 함께 기술안전확보 방안 등에 대해 많은 논의가 이루어지고 있다.', related_words = '{}'::text[] WHERE id = 290;  -- 생성형 인공지능(AI)
UPDATE public.words SET meaning = '생활물가지수(CPI for living necessaries)는 체감물가를 파악하기 위해 일상생활에서 구입 빈도가 높고 지출비중이 높아 가격변동을 민감하게 느끼는 생활필수품을 대상으로 작성한', detailed_meaning = '생활물가지수(CPI for living necessaries)는 체감물가를 파악하기 위해 일상생활에서 구입 빈도가 높고 지출비중이 높아 가격변동을 민감하게 느끼는 생활필수품을 대상으로 작성한 지수이다. 개별 소비자들이 느끼는 물가는 개인이 구입하는 품목이나 구입 빈도에 따라 각각 달라 2025년 현재 소비지출비중이 큰 458개 품목의 가격변동을 평균하여 작성하는 소비자물가지수와는 차이가 있다. 통계청은 이러한 지수물가와 체감물가와의 차이를 설명하기 위하여 일반소비자들이 자주 구입하는 품목과 기본생필품을 중심으로 144 개 품목(쌀, 달걀, 배추, 소주 등)을 선정하여 생활물가지수를 작성하고 있다.', related_words = ARRAY['물가지수','소비자물가지수(CPI)']::text[] WHERE id = 291;  -- 생활물가지수
UPDATE public.words SET meaning = '서학개미란 해외, 주로 미국 주식에 직접 투자하는 한국 개인투자자를 일컫는 신조어이 다.', detailed_meaning = '서학개미란 해외, 주로 미국 주식에 직접 투자하는 한국 개인투자자를 일컫는 신조어이 다. ‘서학’은 서양(특히 미국), ‘개미’는 소액을 모아 투자하는 개인투자자를 비유한 표현이 다. 서학개미는 동학개미와 대비되어 생겨난 용어이다. 동학개미는 2020년 코로나19 당시 국내 증시가 급락했을 때 개인투자자들이 대규모 매수에 나서며 증시 방어 역할을 한 현상을 동학농민운동에 빗대어 표현한 신조어다. 2022년 이후 국내 주식시장이 부진해지는 반면 미국 주식시장은 미달러화 강세, 빅테크 기업 성장 등을 배경으로 호조를 지속하자 국내시장에 실망한 개인투자자들이 미국 등 해외 주식투자를 크게 확대해 나갔는데 이 러한 개인투자자들을 서학개미라 일컫게 되었다. 서학개미의 활발한 해외 투자는 달러화수요를 크게 증가시켜 환율상승 요인으로 작용하는 등 국내 외환시장의 변동성을 확대시키는 요인 중 하나로 평가된다.', related_words = '{}'::text[] WHERE id = 294;  -- 서학개미
UPDATE public.words SET meaning = '선물거래(Futures Transactions)란 공인된 거래소에서 품질, 규격 등이 표준화된 상품의 매매계약을 체결하고 일정기간이 경과한 후에 상품의 인수도와 결제가 이루어지는 거래로서', detailed_meaning = '선물거래(Futures Transactions)란 공인된 거래소에서 품질, 규격 등이 표준화된 상품의 매매계약을 체결하고 일정기간이 경과한 후에 상품의 인수도와 결제가 이루어지는 거래로서 매매계약의 성립과 동시에 상품의 인수도와 결제가 이루어지는 현물거래와 구분된 다. 선물거래와 유사한 개념으로 선도계약(forward contracts)이 있다. 선도계약과 선물거래는 기초 상품을 미래의 특정시점에 특정가격으로 사고 팔기로 약정한 계약이라는 점에서 동일한 성격을 가지나 일반적으로 선도계약은 장외시장에서 거래가 이루어지는 반면 선물거래는 정형화된 거래소를 통해 거래가 이루어지고 일일정산한다는 데 차이가 있다. 선물거래대상이 되는 상품에는 곡물, 귀금속, 원유 등 일반상품과 통화, 채권, 주식 등 금융상품이 있다. 선물거래의 특징으로는 ① 거래소에서 정한 표준화된 조건으로 거래가 이루어지므로 거래의 유동성이 높고, ② 모든 거래자는 거래 이행을 보증하기 위해 청산소(clearing house)에 일정 수준 이상의 증거금(margin)을 예치하여야 하며, ③ 거래소에서 거래가 이루어지면 별도의 조직인 청산소가 거래의 결제 및 이행을 보증하므로 계약불이행 위험(default risk)이 거의 없으며, ④ 최종선물가격을 기준으로 가격변동에 따른당일 손익을 매일 정산한다.', related_words = ARRAY['옵션','스왑']::text[] WHERE id = 295;  -- 선물거래
UPDATE public.words SET meaning = '선물환포지션비율 규제는 국내은행과 외국은행 지점의 선물환포지션(선물 외화자산에서 선물 외화부채를 뺀 값)을 자기자본의 일정 비율 이내로 제한하는 규제로 2010년 10월부터 시행된 제도이다.', detailed_meaning = '선물환포지션비율 규제는 국내은행과 외국은행 지점의 선물환포지션(선물 외화자산에서 선물 외화부채를 뺀 값)을 자기자본의 일정 비율 이내로 제한하는 규제로 2010년 10월부터 시행된 제도이다. 2006년 이후 국내은행 및 외은지점의 선물환 거래가 급증한 것이 단기외채 급증을 가져와 2008년 글로벌 금융위기 당시 외환시장 불안과 자본유출입 변동성 확대의 주된 원인으로 지적되었다. 이에 따라 거시건전성 강화와 외환시장 안정, 단기외채 증가 억제를 목표로 선물환포지션비율 규제 제도가 도입되었다. 도입 당시 국내은행 50%, 외국은행 지점 250%였던 선물환포지션비율 한도는 외환 및 금융시장 상황에 따라 수차례 조정되어 왔으며 2024년 12월 20일부터 각각 75%, 375%로 상향되었는데이는 국내은행들이 외화유동성을 보다 원활하게 확보할 수 있도록 하는 조치였다. 이처럼 선물환포지션비율 규제는 외환건전성 관리의 핵심 정책수단으로 사용됐으며 최근에 는 글로벌 환율변동성 확대와 외환수급 불안에 대응하기 위해 한도가 점차 완화되는 추세에 있다.', related_words = '{}'::text[] WHERE id = 297;  -- 선물환포지션비율 규제
UPDATE public.words SET meaning = '선불형카드는 이용고객이 전자적 또는 자기적 방법으로 일정금액을 저장한 카드를 카드발행자로부터 구입하여 상품구매 또는 서비스 이용시마다 대금이 자동으로 차감 지급되도록 한 카드로서 사용범위에 따라', detailed_meaning = '선불형카드는 이용고객이 전자적 또는 자기적 방법으로 일정금액을 저장한 카드를 카드발행자로부터 구입하여 상품구매 또는 서비스 이용시마다 대금이 자동으로 차감 지급되도록 한 카드로서 사용범위에 따라 범용 선불형카드와 단일목적 선불형카드로 구분된 다. 범용 선불형카드는 광범위한 지역에서 상품 또는 서비스 대금의 지급에 사용될 수 있는 반면 단일목적 선불형카드는 일정지역 또는 특정목적으로만 사용될 수 있다. 선불형카드는 신용카드사가 발행하는 선불카드와 은행 등 금융기관이 발행하는 전자화폐, 전자금융업자가 발행하는 선불전자지급수단으로 구분된다. 대부분의 신용카드사들은 사용한도 가 미리 정해져 있어 그 범위내에서 일반 신용카드처럼 물건이나 서비스를 구매할 수 있고 재충전(top-up)도 가능한 기명 선불카드 또는 무기명 선불카드(기프트카드)를 발행하고 있다. 선불전자지급수단은 IC카드형과 네트워크형으로 분류할 수 있는데 IC카드형은 주로 교통부문을 중심으로 이용되고 있으며 네트워크형은 사이버쇼핑몰 등의 대금결제에 ㅅ 주로 사용되고 있다.', related_words = ARRAY['지급수단','직불카드','전자화폐']::text[] WHERE id = 298;  -- 선불카드/선불전자지급수단
UPDATE public.words SET meaning = '개별 경제지표로는 파악하기 어려운 국민경제의 총체적인 경기수준을 파악하기 위하여경기종합지수를 작성한다.', detailed_meaning = '개별 경제지표로는 파악하기 어려운 국민경제의 총체적인 경기수준을 파악하기 위하여경기종합지수를 작성한다. 경기종합지수는 선행종합지수, 동행종합지수, 후행종합지수 3 개가 작성되고 있으며, 기준년도 수치가 100이 되도록 하여 산출하고 있다. 선행종합지수는 제조업 재고순환지표, 기계류내수출하지수, 국제원자재가격지수, 수출입물가비율, 코스피지수, 장단기금리차, 구인구직비율, 건설주수액, 소비자기대지수 등의 지표처럼 실제경기순환에 앞서 변동하는 개별지표를 가공·종합하여 만든 지수로 향후 경기변동의 단기예측에 이용된다.', related_words = ARRAY['경기종합지수','후행종합지수']::text[] WHERE id = 299;  -- 선행종합지수
